(function(root,factory){if(typeof module==='object'&&module.exports)module.exports=factory();else root.Neuro46Lessons=factory();})(typeof window==='object'?window:globalThis,function(){
'use strict';
const P=(zh,en)=>({zh,en});
const term=(zh,en,meaningZh,meaningEn)=>[P(zh,en),P(meaningZh,meaningEn)];
const step=(zh,en,bodyZh,bodyEn)=>[P(zh,en),P(bodyZh,bodyEn)];
const foundations=[
 {id:'foundation-neuron',title:P('01 · 一颗神经元怎样传消息','01 · How a neuron carries a message'),body:[
  P('神经元是一种细胞。树突通常接收来自其他细胞的输入；胞体包含细胞核并维持细胞运作；轴突把电信号送向远处；轴突末梢与下一个细胞交流。先把这些位置认清，后面的每个机制才有地方发生。','A neuron is a cell. Dendrites usually receive inputs; the soma contains the nucleus and maintains the cell; the axon carries electrical signals over distance; axon terminals communicate with the next cell. Locating these parts gives every later mechanism a place to happen.'),
  P('突触是细胞之间传递信息的接点。发送一侧叫突触前，接收一侧叫突触后。在化学突触，两侧之间有狭窄间隙；发送细胞释放化学物质，接收细胞用受体检测。它们没有因此变成一颗细胞。','A synapse is a communication junction. The sending side is presynaptic; the receiving side is postsynaptic. At a chemical synapse a narrow cleft separates them: the sender releases a chemical and receptors detect it on the receiving cell. The cells do not become one cell.'),
  P('可以把“树突→胞体附近整合→轴突→末梢”当作初学时的路线图，但真实神经元也有特殊连接方式。它是定位框架，不是所有神经元都只能照这个方向工作的绝对规则。','Dendrites → integration near the soma → axon → terminal is a useful beginner route. Real neurons also have specialized arrangements. This is a location framework, not an absolute rule for every neuron.')
 ],sources:[['B','PDF p.80–90']]},
 {id:'foundation-membrane',title:P('02 · 膜、离子和三类“过膜工具”','02 · Membranes, ions and three ways across'),body:[
  P('细胞膜是把细胞内部和外部隔开的薄层。水中的 Na⁺、K⁺、Ca²⁺和 Cl⁻是离子：前面三种带正电，Cl⁻带负电；Ca²⁺每个离子带两个单位的正电。大多数离子不能自由穿过膜的脂质部分。','The membrane is a thin boundary between the inside and outside. Na⁺, K⁺, Ca²⁺ and Cl⁻ are ions dissolved in water: the first three are positive and Cl⁻ is negative; each Ca²⁺ carries two positive charge units. Most ions cannot freely cross the lipid part of the membrane.'),
  P('离子通道提供可选择的通路。有些一直较容易开放，另一些由电压、化学物质或光控制。通道开放只表示“可以通过”，净移动方向还取决于浓度差与电作用力。','Ion channels provide selective pathways. Some are readily open at rest; others are controlled by voltage, chemicals or light. An open channel permits passage, but concentration and electrical forces determine net movement.'),
  P('泵利用能量把物质向不利方向运输，例如 Na⁺/K⁺泵利用 ATP 长期维持梯度。转运体结合底物并改变构象；有些借其他离子的梯度驱动运输。通道、泵和转运体不能只因都跨膜就视为同一种工具。','Pumps use energy to move substances against an unfavorable gradient; the Na⁺/K⁺ pump uses ATP to maintain gradients over time. Transporters bind substrates and change conformation, sometimes using another ion gradient. Channels, pumps and transporters are not interchangeable merely because all cross membranes.')
 ],sources:[['B','PDF p.101–108、115–116']]},
 {id:'foundation-forces',title:P('03 · 离子为什么移动：两种力一起看','03 · Why ions move: consider both forces'),body:[
  P('如果膜可让某种离子通过，随机运动会使它从浓度高的一侧向低的一侧产生净扩散。“净”表示两个方向的移动量相减；不是每一个离子都只朝同一个方向走。','If the membrane permits an ion to pass, random motion produces net diffusion from higher to lower concentration. Net movement is the difference between movements in the two directions; individual ions do not all move one way.'),
  P('电荷也产生作用力：异号相吸、同号相斥。膜内相对负时，电作用力有利于正离子进入，却不利于负离子进入。浓度作用与电作用可能同向，也可能相反，所以只看“里面负”不能决定所有离子的移动。','Charge also exerts a force: opposite charges attract and like charges repel. A negative interior electrically favors cation entry but opposes anion entry. Concentration and electrical influences may reinforce or oppose each other; a negative interior alone cannot determine every ion’s movement.'),
  P('某种离子的平衡电位 E_ion，是这两种作用恰好平衡时的膜电位。此时该离子没有净通量，但仍有随机运动。每种离子有自己的 E；实际 Vm 同时受多种开放通路影响。','An ion’s equilibrium potential, E_ion, is the membrane voltage at which these influences balance. There is no net flux of that ion, but random movement continues. Each ion has its own E; actual Vm depends on multiple open pathways.')
 ],sources:[['B','PDF p.108–115']]},
 {id:'foundation-voltage',title:P('04 · −65 mV 究竟是什么意思','04 · What −65 mV actually means'),body:[
  P('膜电位 Vm 是“细胞内电位减去细胞外电位”。若把外侧当作 0，Vm=−65 mV 表示内侧相对低 65 毫伏。负号描述两侧的比较，不是神经元没有电，也不是整个细胞内部全由负离子组成。','Vm means electrical potential inside minus outside. Taking outside as zero, −65 mV means inside is 65 millivolts lower. The minus sign is a comparison, not an absence of electricity or a claim that the entire interior consists of negative ions.'),
  P('从 −65 变到 −50 mV，数值更接近零，称去极化；从 −65 变到 −75 mV，变得更负，称超极化。动作电位后回向静息电位的过程叫复极。判断变化方向时，先把数字写在数轴上。','A change from −65 to −50 mV is depolarization: the value moves toward zero. From −65 to −75 mV is hyperpolarization: it becomes more negative. Returning toward rest after an AP is repolarization. A number line helps avoid sign errors.'),
  P('很少量电荷在膜两侧分离就能形成电位差，细胞内外的大部分液体仍接近电中性。静息电位是多种离子梯度和通透性共同形成的状态；−65 mV 是常见示例，不是所有细胞固定的数值。','A very small separation of charge across the membrane can create a voltage while bulk fluids remain nearly electrically neutral. Resting voltage depends on gradients and permeability to multiple ions. −65 mV is a common example, not a fixed value for every cell.')
 ],sources:[['B','PDF p.110–118']]},
 {id:'foundation-current',title:P('05 · 电压、电流、电阻、电导分别说什么','05 · Voltage, current, resistance and conductance'),body:[
  P('电压描述电位差；电流 I 描述电荷随时间的净流动。膜的电阻 R 描述通过有多困难；电导 g 描述通过有多容易，二者互为倒数 g=1/R。增加可用通道，通常会增加该通路的电导。','Voltage describes a potential difference; current I describes net charge movement per time. Resistance R describes difficulty of passage; conductance g describes ease of passage, with g=1/R. More available channels usually increase conductance of that pathway.'),
  P('对一个离子通路，电流还取决于 Vm 离它的平衡电位有多远：I_ion=g_ion(Vm−E_ion)。g 是通路开放程度，Vm−E 是带符号的驱动力。门开着但两侧作用平衡时，仍可没有净电流。','For one ion pathway, current also depends on how far Vm lies from its equilibrium potential: I_ion=g_ion(Vm−E_ion). g describes pathway conductance; Vm−E is the signed driving force. An open pathway can still carry zero net current when forces balance.'),
  P('本指南规定正电荷外流为正电流，正电荷内流为负电流。负离子的移动要额外考虑它带负电。单位示例：2 nS×(−120 mV)=−240 pA；nS 是纳西门子，pA 是皮安。','This guide calls outward positive-charge movement positive current and inward positive-charge movement negative current. For anions, account for their negative charge. For example, 2 nS×(−120 mV)=−240 pA; nS means nanosiemens and pA means picoamperes.')
 ],sources:[['B','PDF p.108–115、132–134']]},
 {id:'foundation-signals',title:P('06 · 小输入与动作电位不是同一种信号','06 · Small inputs and action potentials differ'),body:[
  P('突触后电位 PSP 是接收细胞局部膜电位的变化，大小可变，传播时通常逐渐衰减。EPSP 是使发放更容易的兴奋性突触后电位；IPSP 是抑制性突触后电位。判断抑制看发放可能性，不只看电压有没有明显下降。','A postsynaptic potential, PSP, is a local voltage change in the receiving cell. Its size varies and it usually attenuates with distance. An EPSP favors firing; an IPSP is inhibitory. Inhibition concerns firing probability, not merely whether voltage visibly falls.'),
  P('许多输入共同影响轴突初始段，也就是轴突靠近胞体的起始区域。当膜去极化达到能启动再生过程的阈值，电压门控 Na⁺通道正反馈产生动作电位 AP。AP 沿轴突不断再生；它不像小 PSP 那样一路变小。','Many inputs influence the axon initial segment near the soma. If depolarization reaches a threshold that initiates regeneration, voltage-gated Na⁺ channel positive feedback produces an action potential, AP. The AP regenerates along the axon rather than continually shrinking like a passive PSP.'),
  P('因此，“收到了输入”“产生了 EPSP”“发出了 AP”是三个不同判断。一次小输入可能只让 −65 mV 变成 −63 mV；它确实产生了反应，却还没有达到例如 −55 mV 的示例阈值。','Receiving input, producing an EPSP and firing an AP are different events. A small input might shift Vm from −65 to −63 mV: a real response occurred, but it did not reach an illustrative threshold such as −55 mV.')
 ],sources:[['B','PDF p.126–130、176–183']]}
];
const lessons={};
function L(id,summary,why,terms,steps,example,prompt,answer,figure){lessons[id]={summary,why,terms,steps,example,check:{prompt,answer},figure};}
// Every new scenario is a teaching example, not an additional exam observation.

L('c4-t1',P('动作电位是神经元膜电位一次短促、完整的变化。它能沿轴突重复产生，让消息传到远处。','An action potential is a brief, full change in membrane voltage. Regeneration along the axon carries the message over distance.'),P('想象只在树突收到一个小电压变化：它会逐渐衰减。轴突需要一种能沿途重新产生的信号。理解 AP 曲线，就是理解不同通道在什么时候让哪些离子通过。','A small voltage change received on a dendrite tends to fade. Axons need a signal that can be generated again along the route. Reading an AP waveform means explaining which channels allow which ions through at each time.'),[
 term('膜电位 Vm','Membrane potential Vm','细胞内电位减细胞外电位；−65 mV 表示内侧相对更负。','Inside minus outside voltage; −65 mV means the inside is relatively negative.'),
 term('阈值','Threshold','启动 Na⁺通道再生性正反馈所需的膜状态；它不是所有细胞统一的一条数值线。','The membrane condition needed to initiate regenerative Na⁺ positive feedback, not one universal voltage for every cell.'),
 term('电压门控通道','Voltage-gated channel','开放概率随膜电位改变的离子通路。','An ion pathway whose opening probability changes with membrane voltage.'),
 term('电导 g','Conductance g','通路让电荷通过的容易程度；相对电导决定哪个离子更能影响 Vm。','Ease of charge passage; relative conductance determines which ion more strongly influences Vm.')
],[
 step('先有静息状态','Begin at rest','内侧通常比外侧负，K⁺漏通道对静息 Vm 影响较大。Na⁺/K⁺泵长期维持梯度，给后续离子流动提供条件。','The interior is usually negative, with K⁺ leak pathways strongly influencing rest. The Na⁺/K⁺ pump maintains the gradients that make later ion movement possible.'),
 step('输入把膜推到阈值','Input reaches threshold','足够的去极化使 Na⁺通道迅速开放。Na⁺净内流带进正电荷，使 Vm 更正；更正又促使更多 Na⁺通道开放，形成正反馈和快速上升支。','Sufficient depolarization rapidly opens Na⁺ channels. Net Na⁺ influx adds positive charge and raises Vm, which opens more Na⁺ channels. This positive feedback produces the rapid rising phase.'),
 step('上升为什么会停','Why the rise stops','Na⁺通道很快失活，减少内向 Na⁺电流；较慢开放的 K⁺通道此时增加 K⁺外流。两种改变让 Vm 不再继续上升，而向负方向返回。','Na⁺ channels soon inactivate, reducing inward Na⁺ current. Slower K⁺ channels increase K⁺ efflux. Together these changes stop the rise and return Vm toward negative values.'),
 step('为什么会低过静息','Why voltage can fall below rest','K⁺通道不会瞬间全部关闭。残余较高的 K⁺电导暂时把 Vm 拉向更负的 E_K，产生后超极化；随后电导回落，Vm 接近静息。','K⁺ channels do not all close instantly. Residual high K⁺ conductance briefly draws Vm toward the more negative E_K, creating afterhyperpolarization. As that conductance falls, Vm approaches rest.')
],[P('教学示例：静息 −65 mV，输入使膜达到约 −55 mV，随后升到 +30 mV，再降到 −75 mV，最后回到 −65 mV。','Teaching example: Vm starts at −65 mV, reaches an illustrative −55 mV threshold, rises to +30 mV, falls to −75 mV and returns to −65 mV.'),P('从 −55 到 +30 的变化是去极化，但只有高于 0 的区段叫 overshoot。低于原静息值的 −75 mV 是 undershoot。所有数值都是示例；先认清阶段，再解释当时的通道与电流。','The rise from −55 to +30 mV is depolarization, but only the part above 0 is the overshoot. −75 mV, below the original resting level, is the undershoot. Values are illustrative: identify the phase, then explain its channels and current.')],P('为什么不能说“泵把正电荷抽出去，所以产生了每次 AP 的下降支”？','Why is “the pump removes positive charge to produce each AP falling phase” inadequate?'),P('泵维持长期浓度梯度，但毫秒尺度下降支的直接机制是 Na⁺通道失活与 K⁺通道开放所导致的电流改变。必须分清长期准备条件和这次快速变化的直接原因。','The pump maintains long-term gradients. The immediate millisecond-scale falling phase results from Na⁺ channel inactivation and K⁺ channel opening changing the currents. Separate background maintenance from the direct cause of the rapid event.'),'ap');

L('c4-t2',P('Na⁺通道有“关着但能开”“正在开”和“暂时不能再开”三种重要状态。区分它们，才能理解神经元为什么不能连续无限快地放电。','Na⁺ channels can be closed but available, open, or temporarily unavailable through inactivation. This distinction explains why firing cannot repeat infinitely fast.'),P('一扇关着的门不一定有同样的状态：可能随时能打开，也可能暂时被锁住。这个类比只帮助区分可用性；真实变化来自通道蛋白的构象改变。','A closed door might be ready to open or temporarily locked. This analogy distinguishes availability only; real channels change their protein conformation.'),[
 term('关闭而可用','Closed and available','当前不导 Na⁺，但适当去极化可以使它激活。','Not currently conducting Na⁺, but able to activate with suitable depolarization.'),term('开放','Open','通道提供通路；净 Na⁺流动仍取决于驱动力。','A conducting pathway exists; net Na⁺ movement still depends on driving force.'),term('失活','Inactivated','即使仍有去极化，通道也暂时不能正常重新激活。','Temporarily unable to reactivate normally despite continuing depolarization.')
],[
 step('静息时准备好','Ready at rest','许多 Na⁺通道处于关闭而可用态。没有大量 Na⁺通过这些关闭通道，不代表通道已失活。','Many Na⁺ channels are closed and available at rest. Little Na⁺ passing through a closed channel does not mean it is inactivated.'),
 step('去极化快速激活','Depolarization activates rapidly','膜达到适当去极化时，通道迅速开放，通常允许 Na⁺净内流，推动 AP 上升。','Suitable depolarization rapidly opens channels, usually permitting net Na⁺ influx and driving the AP rise.'),
 step('短暂开放后失活','Inactivation follows opening','通道很快进入失活态，持续刺激不能简单地让它一直重复开放。此时神经元暂时缺少足够的可用 Na⁺通道。','Channels soon inactivate. Continuing stimulation cannot simply reopen them repeatedly, leaving too few available Na⁺ channels for an immediate normal second AP.'),
 step('复极后恢复可用','Repolarization restores availability','随着膜复极并经过一定时间，通道解除失活，回到关闭而可用态。恢复可用不是立刻开放，而是重新有被激活的能力。','Repolarization and time allow recovery from inactivation to the closed, available state. Recovery does not mean immediate opening; it means the ability to activate is restored.')
],[P('教学示例：在 AP 后极短时间再次给强刺激，若许多 Na⁺通道仍失活，就不能得到正常第二次 AP。稍后复极使通道恢复，类似输入才又可能成功。','Teaching example: a very strong stimulus immediately after an AP may fail because many Na⁺ channels remain inactivated. Later, recovery during repolarization makes another AP possible.'),P('结构也要区分：典型 Na⁺通道的成孔 α 链是一条多肽上的四个重复结构域。四个“区域”不等于四条独立链，不能照搬典型 K⁺通道四亚基结构。','Also distinguish structure: a typical Na⁺ pore-forming α chain is one polypeptide with four repeated domains. Four domains are not four separate chains; do not substitute the typical four-subunit K⁺ channel structure.')],P('“没有 Na⁺电流”能否单独证明通道失活？','Does absence of Na⁺ current alone prove inactivation?'),P('不能。通道可能普通关闭，也可能开放但 Vm=E_Na 而没有净驱动力。失活的关键是暂时不能被适当去极化重新激活，必须结合膜状态和实验条件判断。','No. It may be ordinarily closed, or open with Vm=E_Na and zero net driving force. Inactivation specifically means temporary inability to reactivate; interpret it using membrane state and experimental conditions.'));

L('c4-t3',P('不应期是一次 AP 后，神经元暂时不能或不容易再发放的时间。它来自通道需要恢复，而不是神经元“没有力气了”。','A refractory period is the time after an AP when firing again is impossible or harder. It reflects channel recovery, not a neuron simply running out of energy.'),P('如果消息刚发出就能立即无限次重复，放电频率和传播方向都会难以控制。区分绝对与相对不应期，可以预测第二次刺激何时能成功。','Channel recovery constrains repeat firing and contributes to propagation direction. Distinguishing absolute from relative refractoriness predicts when a second stimulus can succeed.'),[
 term('绝对不应期','Absolute refractory period','强刺激也不能立即引发第二个正常 AP 的阶段。','A period when even a strong stimulus cannot immediately produce a second normal AP.'),term('相对不应期','Relative refractory period','可以再发放，但通常需要比平时更强的刺激。','A period when firing is possible but usually requires a stronger stimulus.'),term('频率 Hz','Frequency in hertz','每秒事件次数；1 Hz 表示每秒一次。','Events per second; 1 Hz means one event per second.')
],[
 step('刚放电后，Na⁺通道失活','Immediately afterward, Na⁺ channels are inactivated','足够多通道暂时不能被重新激活，Na⁺正反馈无法再次完整建立。这构成绝对不应性的核心原因。','Enough channels are unavailable that regenerative Na⁺ positive feedback cannot be re-established normally. This is the core of absolute refractoriness.'),
 step('部分恢复，但仍不容易','Partial recovery still leaves a challenge','部分 Na⁺通道恢复后，新的 AP 成为可能；但 K⁺电导可能仍高，膜也可能比静息更负。输入必须克服更强的对抗作用。','Once some Na⁺ channels recover, another AP becomes possible. However, K⁺ conductance can remain high and Vm may be below rest, so input must overcome a greater opposing influence.'),
 step('恢复也影响传播','Recovery affects propagation','正常前进的波后方刚被激活，较不容易立即再激活；前方膜仍可用。这有助于向前传播，但人工刺激轴突中部仍可能向两侧传播。','Membrane just behind a normal wave is less available than membrane ahead, helping forward propagation. Artificial stimulation in the middle of an axon can nevertheless propagate both ways.'),
 step('用时间推理想频率上限','Convert recovery time into an ideal bound','若每次 AP 至少要间隔 T 秒，仅由这个限制得到的最大频率是 1/T。它是理论上限，实际细胞还受到其他电流和适应过程限制。','If APs must be at least T seconds apart, this factor alone gives a maximum frequency of 1/T. Actual sustained firing is additionally limited by other currents and adaptation.')
],[P('教学计算：绝对不应期 T=2 ms。先换单位：2 ms=0.002 s；再求 f_max=1/0.002=500 s⁻¹=500 Hz。','Teaching calculation: T=2 ms. Convert first: 2 ms=0.002 s. Then f_max=1/0.002=500 s⁻¹=500 Hz.'),P('500 Hz 只表示给定不应期不允许更快的理想重复，不表示这颗神经元一定持续以 500 Hz 放电。','500 Hz is an ideal upper bound imposed by the stated refractory period, not a claim that the neuron necessarily fires continuously at that rate.')],P('为什么相对不应期的强刺激可能成功，绝对不应期却不行？','Why can stronger input succeed during the relative but not the absolute period?'),P('相对期已经有足够恢复的 Na⁺通道，强输入可以克服残余 K⁺电导或较负的 Vm。绝对期的关键障碍是通道不可用，单纯再加大去极化不能跳过恢复过程。','Enough Na⁺ channels have recovered in the relative period, so stronger input can overcome residual K⁺ conductance or more negative Vm. In the absolute period, channel unavailability is the obstacle; stronger depolarization cannot bypass recovery.'));

L('c4-t4',P('同一神经元在相近条件下，要么没有触发 AP，要么产生完整 AP；输入强度通常通过发放次数和时间安排表达。','For the same neuron under similar conditions, input either fails to trigger an AP or produces a full AP. Input strength is usually represented through spike number and timing.'),P('日常说话可以通过音量表达强弱，但神经元不能简单把每个 AP 越做越大。它主要改变一段时间内发多少次、何时发，以及多少细胞参与。','Speech can encode intensity through loudness, but neurons do not simply make every AP proportionally larger. They change how many spikes occur, their timing, and which cells participate.'),[
 term('全或无','All or none','达到再生条件后产生完整 spike，而不是按刺激大小成比例产生半个或两个大小的 spike。','A full spike follows regenerative threshold rather than spike amplitude scaling proportionally with stimulus strength.'),term('频率编码','Rate coding','用单位时间内的放电次数反映输入。','Representing input through spikes per unit time.'),term('分级电位','Graded potential','如 PSP，大小可以随输入改变，并能相加。','A signal such as a PSP whose amplitude can vary and summate.')
],[
 step('阈下只有局部变化','Subthreshold input gives a local change','较弱输入可能改变 Vm，但没有启动足够的 Na⁺正反馈。这并不是“没有任何反应”，而是没有形成再生 AP。','Weak input can change Vm without initiating sufficient Na⁺ positive feedback. A response may occur, but it is not a regenerative AP.'),
 step('达到阈值产生完整 spike','Threshold produces a full spike','Na⁺进入引起去极化，去极化又打开更多 Na⁺通道。这种自我加强过程使 AP 不像普通小电压变化那样与输入简单成比例。','Na⁺ entry depolarizes the membrane, which opens more Na⁺ channels. This self-reinforcing process makes an AP unlike an ordinary voltage response proportional to input.'),
 step('强输入可以更早再次达阈','Stronger input can bring threshold back sooner','在通道恢复允许的范围内，较强持续输入常让膜更频繁达到阈值，从而增加发放频率。不能越过绝对不应期。','Within limits imposed by channel recovery, stronger sustained input often brings the membrane to threshold more frequently and increases firing rate. It cannot bypass absolute refractoriness.'),
 step('不要把定义扩大','Keep the definition within its conditions','不同细胞的通道、温度和离子环境可不同，因此 AP 波形也可不同。极端持续去极化还可能导致失活和去极化阻滞。','Channels, temperature and ionic conditions differ across cells, so waveforms can differ. Extreme persistent depolarization can also produce inactivation and depolarization block.')
],[P('教学示例：弱输入只让 Vm 从 −65 到 −60 mV，未达示例阈值 −55 mV，因此无 AP。中等持续输入产生 5 个 spike，较强输入产生 10 个；若条件相近，每个正常 spike 的振幅大致相近。','Teaching example: weak input shifts Vm from −65 to −60 mV, below an illustrative −55 mV threshold, so no AP occurs. Moderate sustained input produces five spikes and stronger input ten, with roughly similar normal spike amplitudes under similar conditions.'),P('类比可以是“按铃次数变多”，但真实频率来自膜电流、阈值和恢复过程，不能只用类比代替机制。','“Ringing a bell more often” is a useful analogy, but actual firing rate comes from membrane currents, threshold and recovery. The analogy does not replace those mechanisms.')],P('两个小 EPSP 相加触发一个 AP，是否表示两个 AP 振幅相加？','If two small EPSPs combine to trigger an AP, have two AP amplitudes been added?'),P('没有。相加的是输入端的分级电位，合成结果达到阈值后才触发一个再生 AP。PSP 的总和与 AP 的全或无属于不同层次。','No. Graded input potentials summate, and their combined effect then triggers one regenerative AP at threshold. PSP summation and all-or-none AP generation describe different levels.'));

L('c4-t5',P('离子电流的大小同时取决于“通路有多容易通过”和“推动净移动的作用有多大”。开放通道只是条件之一。','Ionic current depends both on how easily charge can pass and on the force driving net movement. Channel opening is only one requirement.'),P('只数开放通道会漏掉一个关键问题：如果 Vm 已经等于该离子的平衡电位，更多开放通道也不会产生净电流。公式把这两项分开，帮助预测方向与大小。','Counting open channels misses a crucial point: if Vm equals that ion’s equilibrium potential, more open channels still produce no net current. The equation separates conductance and driving force to predict direction and size.'),[
 term('I_ion','Ionic current','该离子造成的膜电流；本页以正电荷外流为正。','Membrane current carried by that ion; outward positive-charge movement is positive here.'),term('g_ion','Ionic conductance','该通路让电荷通过的容易程度，常用 nS。','Ease of charge passage through the pathway, often measured in nS.'),term('Vm−E_ion','Driving force','实际膜电位与该离子平衡电位的差，单位 mV；其符号参与决定电流方向。','Actual voltage minus that ion’s equilibrium potential, in mV; its sign helps determine current direction.')
],[
 step('先确认有没有通路','Check for a pathway','如果 g=0，这条通路相当于不导电。即使浓度与电作用很强，离子也不能通过这条关闭通路形成电流。','With g=0 the pathway does not conduct. Even strong concentration and electrical influences cannot generate current through that closed pathway.'),
 step('再比较 Vm 和 E','Compare Vm with E','E 是该离子两种作用平衡时的电压。Vm 离 E 越远，驱动力绝对值通常越大；当二者相等，正反向流动相抵，净电流为零。','E is the voltage at which the ion’s influences balance. The farther Vm lies from E, the larger the driving-force magnitude. At equality, opposing fluxes balance and net current is zero.'),
 step('把两项相乘','Multiply the two factors','I_ion=g_ion(Vm−E_ion)。先计算括号里的带符号差值，再乘电导。对阳离子，负电流对应净内流；分析阴离子时还须考虑负电荷。','Use I_ion=g_ion(Vm−E_ion). Compute the signed voltage difference first, then multiply by conductance. For cations, negative current means net influx; for anions, account for negative charge.'),
 step('应用到 AP','Apply this to the AP','上升支中 Na⁺通道越来越多开放，但 Vm 同时向 E_Na 靠近，驱动力变小。于是电流不只跟 g_Na 同步，最大内流不必出现在电压峰值。','During the upstroke, more Na⁺ channels open while Vm approaches E_Na and driving force decreases. Current therefore need not track g_Na alone, nor peak at the voltage peak.')
],[P('教学计算：g_Na=2 nS，Vm=−65 mV，E_Na=+55 mV。驱动力=−65−55=−120 mV；I_Na=2×(−120)=−240 pA，表示内向正电荷电流。','Teaching calculation: g_Na=2 nS, Vm=−65 mV and E_Na=+55 mV. Driving force=−65−55=−120 mV. I_Na=2×(−120)=−240 pA, an inward positive-charge current.'),P('保持 g=2 nS，但让 Vm=+55 mV，则 I=2×0=0 pA。通道仍可开放；零电流来自驱动力为零，不是通道消失。','Keep g=2 nS but set Vm=+55 mV: I=2×0=0 pA. Channels can remain open; zero current comes from zero driving force, not disappearance of the pathway.')],P('把 g 加倍，是否一定使电流加倍？','Does doubling g always double current?'),P('只有其他条件，尤其 Vm−E，保持不变时才可这样预测。若膜电位或离子梯度也变了，必须重新计算两项乘积。','Only if other conditions, especially Vm−E, stay fixed. If membrane voltage or ionic gradients also change, recalculate the product.'));

L('c4-t6',P('平衡电位告诉我们：某种离子在什么膜电位下没有净移动。改变内外浓度，就会改变这个平衡点。','An equilibrium potential is the membrane voltage at which one ion has no net movement. Changing inside or outside concentrations shifts that balance point.'),P('题目改变细胞外 K⁺时，不应直接猜“整条 AP 曲线上升或下降”。先算它怎样改变 E_K，再看当时是不是 K⁺通路更能控制 Vm。','When extracellular K⁺ changes, do not immediately shift the entire AP curve. First determine the effect on E_K, then ask whether K⁺ pathways strongly influence Vm during the phase considered.'),[
 term('浓度比 out/in','Outside/inside ratio','同一离子细胞外浓度除以细胞内浓度；两者须用相同单位。','Outside concentration divided by inside concentration of the same ion, using matching units.'),term('价态 z','Valence z','带电数和符号：K⁺为 +1，Ca²⁺为 +2，Cl⁻为 −1。','Charge number and sign: +1 for K⁺, +2 for Ca²⁺ and −1 for Cl⁻.'),term('Nernst 方程','Nernst equation','由温度、价态和浓度比求单一离子平衡电位的关系；它不直接给出多离子膜的完整 Vm。','A relation giving one ion’s equilibrium potential from temperature, valence and concentration ratio, not the complete Vm of a multi-ion membrane.')
],[
 step('先看浓度怎样推离子','Identify the concentration influence','通常细胞内 K⁺较多，所以浓度差推动 K⁺向外。K⁺外流留下相对负的内侧，电作用又吸引 K⁺向内；某一负电位下二者可平衡。','K⁺ is usually more concentrated inside, favoring outward diffusion. K⁺ efflux leaves the interior relatively negative, which electrically attracts K⁺ inward. These influences can balance at a negative voltage.'),
 step('用方程表达这个平衡','Express the balance mathematically','E_ion=(RT/zF)ln(out/in)。R 为气体常数，T 为绝对温度 K，F 为法拉第常数；用这组常数得伏特，再换成毫伏。相同温度时主要比较浓度比和 z。','E_ion=(RT/zF)ln(out/in), where R is the gas constant, T absolute temperature in kelvin and F the Faraday constant. These constants give volts, converted to millivolts. At fixed temperature, compare the ratio and z.'),
 step('增加外 K⁺会怎样','Predict increased extracellular K⁺','外 K⁺增多使向外的浓度作用减弱，不再需要那么负的内侧来平衡它，因此 E_K 变得较不负。若静息 K⁺电导占较大权重，静息 Vm 也常变得较不负。','More external K⁺ weakens the outward concentration influence. Less negative inside voltage is needed to balance it, so E_K becomes less negative. If K⁺ conductance has substantial resting weight, resting Vm commonly follows.'),
 step('最后对应波形与离子','Connect the result to the waveform','K⁺变化优先影响静息和 undershoot；Na⁺梯度更直接影响峰值。对 Cl⁻等阴离子，z 为负会反转浓度比的符号关系，不能套阳离子口诀。','K⁺ changes primarily affect rest and undershoot; the Na⁺ gradient affects the peak more directly. Negative z reverses the ratio/sign relation for anions such as Cl⁻, so cation rules cannot be copied blindly.')
],[P('教学计算：取 37°C，单价阳离子可近似用 E≈61.5 mV×log₁₀(out/in)。若 K⁺外为 5 mM、内为 100 mM，E_K≈61.5×log₁₀(0.05)≈−80 mV。','Teaching calculation: at 37°C, a monovalent cation approximately follows E≈61.5 mV×log₁₀(out/in). With K⁺ at 5 mM outside and 100 mM inside, E_K≈61.5×log₁₀(0.05)≈−80 mV.'),P('仅把外 K⁺改为 10 mM，E_K≈61.5×log₁₀(0.10)=−61.5 mV，确实较不负。这个计算得到的是 E_K；实际 Vm 还要考虑其他通路，不能直接宣称它必定等于 −61.5 mV。','Changing only outside K⁺ to 10 mM gives E_K≈61.5×log₁₀(0.10)=−61.5 mV, less negative. This is E_K; actual Vm still depends on other pathways and need not equal −61.5 mV.')],P('为什么改变 E_K 不一定使 AP 峰值同样移动？','Why need the AP peak not shift by the same amount as E_K?'),P('不同阶段的主导电导不同。峰值更直接受 Na⁺相关性质影响；在仅改 E_K 的课堂简化模型下可近似不变。真实变化仍取决于具体膜状态，不能把简化结论当成所有条件的保证。','Different conductances dominate different phases. Na⁺ properties more directly influence the peak, which can remain approximately unchanged in the classroom model that changes only E_K. Actual effects depend on membrane state; the simplification is not a universal guarantee.'));

L('c4-t7',P('轴突通过相邻膜依次产生 AP 传递信号。直径和髓鞘改变传得多快；总长度改变要走多远。','An axon carries a signal by regenerating APs in successive membrane regions. Diameter and myelin affect speed; total length determines travel distance.'),P('像一排依次被点亮的灯，每一处都重新产生信号，远端才能保留完整 AP。这里不是同一批 Na⁺从轴突一端跑到另一端；类比只表示局部再生的顺序。','Like lamps lighting in sequence, each region generates the signal again. This is not the same batch of Na⁺ traveling from one axon end to the other; the analogy represents the sequence of local regeneration.'),[
 term('轴向电阻','Axial resistance','电流沿轴突内部传播遇到的阻碍。','Resistance to current spreading through the axon interior.'),term('髓鞘','Myelin','包在部分轴突外的绝缘层，提高膜电阻并降低膜电容。','Insulating layers around parts of an axon that increase membrane resistance and reduce capacitance.'),term('郎飞结','Node of Ranvier','髓鞘之间露出的短段膜，富含使 AP 再生的电压门控通道。','Short exposed membrane gaps between myelin segments, rich in channels supporting AP regeneration.'),term('电容','Capacitance','使膜电压改变一定量需要储存多少电荷；较低电容意味着同样电压变化所需电荷较少。','Charge storage needed for a voltage change; lower capacitance requires less charge for the same change.')
],[
 step('局部电流影响前方','Local current affects membrane ahead','一个区域去极化后，电流沿内部向相邻区域扩散。相邻可兴奋膜达到阈值，开放自己的 Na⁺通道，产生新的完整 AP。','After one region depolarizes, current spreads internally to adjacent membrane. If that excitable membrane reaches threshold, its own Na⁺ channels generate a new full AP.'),
 step('粗轴突减少沿路阻力','A wider axon reduces axial resistance','直径增加使内部电流传播更容易，因此相邻区域更容易被迅速去极化。这里改变的是传导性质，不是每个 spike 的大小。','Larger diameter makes internal current spread easier, helping adjacent regions depolarize rapidly. This changes conduction properties, not the size of each spike.'),
 step('髓鞘减少漏失与充电负担','Myelin reduces leakage and charging demand','膜电阻提高，使电流较少从节间漏出；膜电容降低，使节间电压改变所需电荷较少。电流能更有效地影响下一个结。','Higher membrane resistance reduces internodal leakage; lower capacitance reduces charge needed to change voltage. Current can influence the next node more effectively.'),
 step('在结区重新产生 AP','Regenerate at nodes','节间主要被动传流，结区重新产生 AP，这就是跳跃传导。正常波后方的膜刚放电、处于不应状态，也有助于向前传播。','Current mainly spreads passively between nodes, while nodes regenerate APs: saltatory conduction. Recently activated refractory membrane behind the normal wave also helps forward propagation.')
],[P('教学计算：速度 v=20 m/s，距离 L=0.40 m，则到达时间 t=L/v=0.020 s=20 ms。若长度加倍到 0.80 m 而速度保持 20 m/s，到达时间变成 40 ms。','Teaching calculation: v=20 m/s and L=0.40 m give t=L/v=0.020 s=20 ms. Doubling length to 0.80 m at the same speed gives 40 ms.'),P('因此“更长”通常意味着要等更久，不代表局部传导速度更快。若失去髓鞘，更多电流漏失，还可能慢到无法让下一个区域达到阈值，造成传导失败。','Longer distance therefore means more waiting, not faster local conduction. Demyelination increases leakage and may prevent the next region reaching threshold, causing conduction failure.')],P('为什么 AP 沿轴突不衰减，却仍需要传播时间？','Why does an AP take time to propagate even though it does not attenuate?'),P('不衰减来自沿途再生，每一段仍需经历电流传播、充电和通道激活。保持振幅与瞬间到达是两个不同性质。','Amplitude is maintained by regeneration, but current spread, membrane charging and channel activation still take time. Preserved amplitude does not imply instantaneous arrival.'));

L('c4-t8',P('相似的信号失败可以由不同分子干预造成。分析毒素时，要从通道怎样被改变开始，而不是只背“会瘫痪”。','Similar signaling failure can result from different molecular interventions. Analyze what changes in the channel rather than memorizing only an outcome such as paralysis.'),P('正常放电既需要 Na⁺通道能迅速开放，也需要它们适时失活、随后恢复。阻止通过和破坏正常关闭／恢复，都可能让信息无法正常传递。','Normal firing needs Na⁺ channels to open rapidly, inactivate appropriately and then recover. Preventing conduction or disrupting normal gating can both impair communication.'),[
 term('TTX／saxitoxin','TTX/saxitoxin','可阻断敏感电压门控 Na⁺通道的经典毒素例子。','Classical examples that block susceptible voltage-gated Na⁺ channels.'),term('Batrachotoxin','Batrachotoxin','使 Na⁺通道异常保持活性、破坏正常门控的例子。','An example that promotes persistent Na⁺ channel activity and disrupts normal gating.'),term('去极化阻滞','Depolarization block','膜持续去极化却不能正常重复发放的状态，常与 Na⁺通道不可用有关。','Failure of normal repetitive firing during persistent depolarization, often involving Na⁺ channel unavailability.')
],[
 step('先写正常对照','Define the normal comparison','正常 Na⁺内流启动再生上升支，随后通道失活、膜复极并恢复。这个循环才能产生一串分开的 spike。','Normal Na⁺ influx initiates the upstroke, followed by inactivation, repolarization and recovery. This cycle supports separate repeated spikes.'),
 step('阻断型干预','Consider conduction blockade','TTX 或 saxitoxin 减少通过敏感 Na⁺通道的内流，使膜难以建立再生正反馈，因此 AP 的产生或传播受损。','TTX or saxitoxin reduces influx through susceptible Na⁺ channels, impairing regenerative positive feedback and therefore AP generation or propagation.'),
 step('持久活性型干预','Consider persistent abnormal activity','Batrachotoxin 破坏正常门控，促成持久活性与去极化。这不是“正常 spike 一直连续播放”；正常复极和重复放电节律会被破坏。','Batrachotoxin disrupts gating and promotes persistent activity and depolarization. This is not an endless train of normal spikes: normal repolarization and repeat firing are disrupted.'),
 step('把靶点连到传递','Link target to transmission','局部麻醉剂如 lidocaine 也可抑制 Na⁺通道介导的传导。无论例子是什么，都依次解释靶点、电流、AP 和下游信号，避免由相似结果推成同一机制。','Local anesthetics such as lidocaine can also inhibit Na⁺ channel-mediated conduction. For any example, connect target, current, AP and downstream signaling rather than inferring a shared mechanism from a shared outcome.')
],[P('教学情境：A 处理后快速内向 Na⁺电流明显减少；B 处理后电流门控异常且膜持续去极化。两组都可能失去正常信号传递，但证据分别指向阻断和异常持久活性。','Teaching scenario: treatment A reduces the rapid inward Na⁺ current; treatment B disrupts gating and produces persistent depolarization. Both may impair normal transmission, but the evidence indicates blockade versus abnormal persistent activity.'),P('这些是机制推理示例。仅观察“没有运动反应”，还不足以确定问题发生在 Na⁺通道、递质释放还是肌肉受体。','These examples illustrate mechanism inference. Observing no movement alone cannot locate the defect in Na⁺ channels, transmitter release or muscle receptors.')],P('“通道开得久”为什么不等于“正常发放频率更高”？','Why is longer channel opening not equivalent to a higher normal firing rate?'),P('正常重复发放需要开放、失活、复极和恢复的完整循环。持续异常开放会改变膜状态并破坏这个循环，所以不能把持续电流当成一串正常 AP。','Normal repetitive firing requires the complete opening–inactivation–repolarization–recovery cycle. Abnormally persistent opening changes membrane state and disrupts that cycle; sustained current is not a normal AP train.'));

L('c4-t9',P('电压钳控制膜电位，再测为维持它需要多少电流；膜片钳用小片膜上的高阻封接，观察通道或整个细胞的电流。','Voltage clamp controls membrane voltage and measures the current needed to hold it. Patch clamp uses a high-resistance seal on a membrane patch to record channel or whole-cell currents.'),P('只看 AP 曲线，不能分清 Na⁺电流与 K⁺电流各贡献多少，因为电压和通道会同时变化。实验需要固定一个变量，才能更清楚观察另一个。','An AP waveform alone cannot separate Na⁺ from K⁺ current because voltage and channels change together. Controlling one variable makes another easier to interpret.'),[
 term('命令电压','Command voltage','实验者要求细胞膜维持的目标电位。','The target membrane voltage imposed by the experimenter.'),term('反馈','Feedback','仪器比较实际与目标电压，再调节注入电流以减少差距。','The instrument compares actual and target voltage, adjusting injected current to reduce the difference.'),term('高阻封接','High-resistance seal','微电极与膜紧密贴合，减少旁路漏电，使小通道电流可被测到。','A tight electrode–membrane seal minimizing leakage so small channel currents can be recorded.')
],[
 step('提出可分离的问题','Ask a separable question','例如问“相同电压变化下，早期和晚期电流是否不同”。先明确改变什么、测量什么，而不是把两者都叫作电信号。','For example: do early and late currents differ after the same voltage step? Define what is manipulated and what is measured rather than calling both simply electrical signals.'),
 step('固定 Vm，观察 I','Control Vm and observe I','电压钳通过反馈维持命令电压，记录所需电流。固定电压不会使通道都停止工作；它让电流时间变化更容易分析。','Voltage-clamp feedback holds the command voltage while recording required current. Fixed voltage does not stop channels working; it makes current time courses easier to analyze.'),
 step('用对照分离电流来源','Use comparisons to isolate current sources','总记录可能含多种离子、漏电与充电成分。合适的通道阻断、离子替换及记录处理帮助分离 Na⁺和 K⁺成分；一次总电流不能直接归给唯一通道。','A total recording can include multiple ionic, leak and charging components. Suitable blockers, ion substitution and recording analysis help separate Na⁺ and K⁺ components; total current alone does not uniquely identify one channel.'),
 step('缩小到膜片或改变配置','Choose patch configuration and scale','小膜片可显示单通道开闭事件；whole-cell 配置则记录整个细胞的膜电流。膜片钳不是只能看单通道，电压钳也不是固定电流。','A small patch can reveal single-channel openings; whole-cell configuration records currents across the cell membrane. Patch clamp is not restricted to single channels, and voltage clamp does not fix current.')
],[P('教学情境：把 Vm 从 −65 mV 阶跃到 0 mV，先观察到短暂内向电流，稍后有较慢外向电流。不能只凭这个形状命名离子；加入选择性阻断比较后，才更有依据区分早期 Na⁺与延迟 K⁺成分。','Teaching scenario: step Vm from −65 to 0 mV and observe a transient inward current followed by slower outward current. Shape alone does not name the ions. Comparisons with selective blockers provide stronger evidence for early Na⁺ and delayed K⁺ components.'),P('Hodgkin 与 Huxley 使用乌贼巨轴突研究这些时间关系。实验思想的重点是控制和分离，不是“看见一条曲线就证明全部分子机制”。','Hodgkin and Huxley studied these time relationships in the squid giant axon. The central experimental idea is control and separation, not proving every molecular mechanism from one curve.')],P('为何“把电压固定”不意味着“电流一定为零”？','Why does holding voltage constant not imply zero current?'),P('只要通道开放且 Vm 与其 E 不同，就可有离子电流。仪器施加补偿电流来维持电压；它控制电位，不是消除所有电荷流动。','Open channels can carry ionic current whenever Vm differs from their E. The instrument supplies compensating current to hold voltage; it controls potential rather than eliminating all charge flow.'));

L('c4-t10',P('光遗传把特定光敏蛋白放进细胞，再用光改变离子流动，从而改变细胞发放的可能性。','Optogenetics places particular light-sensitive proteins in cells, then uses light to change ion movement and firing probability.'),P('光本身不会自动使所有神经元兴奋。关键是哪个细胞表达了哪种蛋白，以及蛋白被照亮后怎样运输电荷。','Light does not automatically excite every neuron. The important questions are which cells express which protein and how illumination changes charge movement.'),[
 term('Opsin','Opsin','这里指能对光作出反应、用于控制细胞膜活动的蛋白。','Here, a light-sensitive protein used to control membrane activity.'),term('ChR2','Channelrhodopsin-2','经典蓝光门控非选择性阳离子通道。','A classic blue-light-gated, nonselective cation channel.'),term('Halorhodopsin','Halorhodopsin','经典黄光驱动、向内运输 Cl⁻的主动泵。','A classic yellow-light-driven active pump transporting Cl⁻ inward.')
],[
 step('先确认表达位置','Establish expression','只有表达相应 opsin 的细胞才有预期的直接蛋白反应。选择表达细胞是控制特定细胞群的重要来源。','The intended direct protein response requires the relevant opsin. Choosing expressing cells is an important source of cell-population selectivity.'),
 step('匹配光与蛋白','Match illumination to protein','蓝光可激活经典 ChR2，打开阳离子通路。在常见静息状态，净内向正电荷电流使膜去极化，可能提高发放概率。','Blue light activates classic ChR2, opening a cation pathway. At common resting voltages, net inward positive-charge current depolarizes the membrane and can increase firing probability.'),
 step('区分另一种运输机制','Distinguish the pump mechanism','经典 halorhodopsin 用光能把 Cl⁻向内泵入，通常使内侧更负并抑制。它不是被动 Cl⁻通道，不能把通道的平衡逻辑直接当作泵的工作方式。','Classic halorhodopsin uses light energy to pump Cl⁻ inward, usually making the interior more negative and inhibiting. It is not a passive Cl⁻ channel, so passive-channel equilibrium reasoning is not its pumping mechanism.'),
 step('加入匹配对照','Add matched controls','未表达 opsin 的细胞接受相同光照，帮助排除光照本身等影响。还要匹配细胞类型、记录条件和照明条件，才能把差异合理归给蛋白。','Illuminate matched nonexpressing cells in the same way to examine effects of light itself. Match cell type, recording and illumination conditions before attributing differences to the protein.')
],[P('教学情境：相同静息条件下，表达 ChR2 的细胞受蓝光后更易达阈；未表达组接受相同蓝光却没有这种改变，支持 opsin 依赖性。','Teaching scenario: under matched resting conditions, blue light makes a ChR2-expressing cell more likely to reach threshold, while matched nonexpressing cells do not show that change. This supports opsin dependence.'),P('若换成 halorhodopsin，需要改变对光和离子运输的预测，不能继续套用“蓝光→Na⁺进入”。即使 ChR2 的净电流常可用 Na⁺内流简述，它也不是只通 Na⁺。','Changing to halorhodopsin changes the predictions for illumination and ion transport; do not reuse “blue light → Na⁺ entry.” Even for ChR2, Na⁺ influx is only a simplification because the channel is not Na⁺-exclusive.')],P('若照光后细胞不放电，能否立刻说 opsin 没有工作？','If a cell does not fire after illumination, does that immediately prove the opsin failed?'),P('不能。要检查是否有 Vm 或电流变化，以及变化是否足以达阈。蛋白可以引起去极化而未触发 AP；表达、光照与细胞条件也需核对。','No. Check whether current or Vm changed and whether the change reached threshold. A working protein can depolarize a cell without triggering an AP; expression, illumination and cellular conditions also need checking.'));

L('c5-t1',P('电突触是在两颗细胞之间建立直接通道，让离子电流从一侧影响另一侧。它与释放递质的化学突触不同。','An electrical synapse provides direct channels between cells, allowing ionic current in one cell to influence another. It differs from transmitter-releasing chemical transmission.'),P('有时一群细胞需要很快地一起改变活动。直接电耦联减少中间步骤，能够帮助同步，但不保证每次都在另一细胞产生 AP。','Some cell groups need to change activity rapidly together. Direct electrical coupling reduces intermediate steps and can support synchrony, without guaranteeing a postsynaptic AP every time.'),[
 term('Gap junction','Gap junction','把两个细胞内部通过通道连接起来的间隙连接。','A junction containing channels that connect the interiors of two cells.'),term('Connexin 与 connexon','Connexin and connexon','connexin 是蛋白单位；通常六个组成一个 connexon 半通道。','Connexin is a protein unit; usually six form one connexon hemichannel.'),term('电耦联','Electrical coupling','一个细胞的电流／电位变化可以直接影响另一个细胞。','Direct influence of one cell’s current/voltage change on another cell.')
],[
 step('两侧各建半个通道','Each cell supplies a half-channel','一侧膜上的六个 connexin 通常组成一个 connexon；另一侧也有一个。两个 connexon 对接才构成跨越两细胞的完整通道。','Six connexins usually make a connexon in each membrane. One connexon from each cell docks with the other to form the complete intercellular channel.'),
 step('电流直接通过','Current passes directly','当两细胞之间存在驱动电流的条件，离子可通过通道流动，改变接收细胞的电位，不必先释放化学递质再等待受体结合。','With an appropriate driving difference between cells, ions move through channels and influence the receiving cell’s voltage without transmitter release and receptor binding first.'),
 step('速度与方向','Consider speed and direction','这种直接连接延迟很小，常可双向传递。某些连接有整流性，所以“所有电突触都完全双向”过于绝对。','Direct coupling has very little delay and is often bidirectional. Some junctions rectify, so completely bidirectional behavior is not universal.'),
 step('由耦联到同步','From coupling to synchrony','邻近细胞的电位互相影响，可使活动时间更接近。小的阈下变化也可传递，是否产生 AP 仍取决于接收细胞的阈值和其他输入。','Mutual voltage influence can bring neighboring activity closer in time. Subthreshold changes can also pass; AP generation still depends on threshold and other inputs.')
],[P('教学计数：一个完整连接通道通常需要 2 个 connexon，每个含 6 个 connexin，因此共 12 个 connexin。题目若问“一个 connexon”，答案是 6；问“几个 connexon 对接”，答案是 2。','Teaching count: a complete channel usually contains two connexons, each with six connexins, totaling twelve connexins. One connexon contains six; two connexons dock.'),P('这不是 12 个独立细胞，也不需要囊泡释放。原卷“传离子”和“同步邻近细胞”两个描述都可以真实成立，只是一个说机制，一个说功能。','This does not mean twelve cells and does not require vesicle release. Both “transfers ions” and “synchronizes neighboring cells” can be true: one describes mechanism, the other function.')],P('电突触没有递质释放，是否就不会改变突触后电位？','If an electrical synapse has no transmitter release, can it still alter postsynaptic voltage?'),P('可以。直接离子电流就能改变电位。化学受体不是所有细胞间电位影响的必要条件，但完整通道与驱动条件仍然必要。','Yes. Direct ionic current can change voltage. Chemical receptors are not required for every intercellular voltage effect, although a conducting connection and driving conditions remain necessary.'));

L('c5-t2',P('Loewi 将第一颗心的浴液转移给第二颗心，发现减慢心率的作用也能转移。这支持存在可扩散的化学信号。','Loewi transferred bathing solution from one heart to another and found that the slowing effect transferred too. This supported a diffusible chemical signal.'),P('实验要区分“神经直接通电使心变慢”和“神经释放某种物质使心变慢”。让第二颗心不接受同样的神经刺激，却接收第一颗心的液体，是关键安排。','The experiment distinguishes direct electrical action from release of a chemical mediator. The key arrangement gives the second heart the first heart’s solution without the same direct nerve stimulation.'),[
 term('迷走神经','Vagus nerve','在这个实验中，刺激它会减慢第一颗蛙心。','The nerve whose stimulation slows the first frog heart in this experiment.'),term('浴液','Bathing solution','包围实验心脏的液体，可携带释放到其中的物质。','Fluid surrounding the experimental heart, able to carry released substances.'),term('观察与推断','Observation and inference','观察是测到心率下降；推断是转移液中存在介导作用的物质。','Observation is the measured slowing; inference is that a substance in transferred fluid mediates it.')
],[
 step('记录第一颗心','Observe the first heart','先测心率，再刺激迷走神经，观察心率下降。这一步本身还不能区分直接电作用和化学介质。','Measure heart rate, stimulate the vagus and observe slowing. This observation alone does not separate a direct electrical effect from chemical mediation.'),
 step('把浴液交给第二颗心','Transfer solution to the second heart','第二颗心没有接受第一颗心的直接神经刺激，却也在接收浴液后减慢。可转移的因素存在于液体中。','The second heart also slows after receiving solution despite not receiving the first heart’s direct nerve stimulation. A transferable factor is present in the fluid.'),
 step('解释支持什么','Explain what the result supports','两心无需直接电连接，浴液却能传递作用，因此支持可扩散化学介质。该物质后来被认作 ACh；仅凭首次转移现象还不能得出它的全部分子身份。','The effect transfers without a direct electrical connection, supporting a diffusible mediator. It was later identified as ACh; the transfer result alone does not establish its complete molecular identity.'),
 step('排除转移流程本身','Control for the transfer procedure','转移未刺激条件的浴液，保持体积、溶液条件和操作一致。若只有刺激后的液体产生相应变化，化学介质推断更有说服力。','Transfer unstimulated-condition solution with matched volume, solution conditions and handling. A selective effect of stimulated solution strengthens the chemical-mediator inference.')
],[P('教学情境：第一心从每分钟 60 次降到 40 次；第二心原来 60 次，接受刺激后浴液也降到 40 次；接受未刺激浴液的对照仍约 60 次。数字只用于说明对照逻辑。','Teaching scenario: heart 1 slows from 60 to 40 beats/min; heart 2 also slows from 60 to 40 after stimulated solution, while an unstimulated-solution control remains near 60. These illustrative numbers explain the comparison.'),P('答题顺序是“第一心发生什么→第二心收到什么并发生什么→说明什么→对照是什么”。不要把第二颗心说成被同一根电极直接刺激。','Answer in order: what happened in heart 1 → what heart 2 received and did → inference → control. Do not describe heart 2 as directly stimulated by the same electrode.')],P('这个实验能否证明所有突触都使用 ACh？','Does this experiment prove that all synapses use ACh?'),P('不能。它支持该实验系统的化学介导，不排除其他递质或其他位置的电突触。实验结论的范围不能大于实际测试范围。','No. It supports chemical mediation in this preparation without excluding other transmitters or electrical synapses elsewhere. The conclusion must not exceed the experiment’s scope.'));

L('c5-t3',P('突触结构告诉我们发送端、释放位置和接收端在哪里。Gray I／II 是形态分类，常与兴奋或抑制相关，但不是直接功能测量。','Synaptic structure locates the sender, release site and receiver. Gray I/II are morphological classes commonly associated with excitation or inhibition, not direct functional measurements.'),P('看图时先分清两侧，才能避免把融合写到突触后膜、把受体写到释放囊泡上。结构分类和化学／电突触分类还属于不同问题。','Identifying the two sides prevents placing fusion at the postsynaptic membrane or receptors on release vesicles. Morphological classes and chemical/electrical classification address different questions.'),[
 term('Active zone','Active zone','突触前膜上集中组织递质释放装置的区域。','A presynaptic membrane region organizing transmitter-release machinery.'),term('Postsynaptic density，PSD','Postsynaptic density, PSD','突触后侧富集受体与支架蛋白、显微镜下较致密的结构。','A dense postsynaptic structure enriched in receptors and scaffolding proteins.'),term('Axodendritic／axosomatic／axoaxonic','Axodendritic/axosomatic/axoaxonic','前突触轴突分别接到树突、胞体或另一轴突；名称描述位置。','A presynaptic axon contacting a dendrite, soma or another axon; the names specify location.')
],[
 step('定位发送和接收两侧','Locate sender and receiver','突触前侧可见释放囊泡与 active zone；递质跨越 cleft 后到达突触后受体。cleft 是两膜之间的空间，不是连接细胞内部的 gap-junction 通道。','Vesicles and an active zone lie presynaptically; transmitter crosses the cleft to postsynaptic receptors. The cleft is extracellular space, not a gap-junction channel connecting interiors.'),
 step('识别 Gray I','Recognize Gray I','经典 I 型两侧致密结构不对称，突触后较厚，囊泡常较圆，通常与兴奋性传递相关。要把“结构特征”和“通常功能”分别写清。','Classical type I is asymmetric, with a thicker postsynaptic density and commonly round vesicles, and is usually associated with excitation. State structural features separately from the usual functional association.'),
 step('用相同维度识别 Gray II','Compare Gray II on the same dimensions','II 型较对称、囊泡常较扁，通常与抑制相关。它仍可属于化学突触，不能因“II”就称为电突触。','Type II is more symmetric, commonly with flatter vesicles, and usually associated with inhibition. It can still be a chemical synapse; type II does not mean electrical.'),
 step('功能最终要看响应','Verify function through response','受体和离子条件决定通道开放后电流及发放概率怎样变化。形态提供提示，必要时仍需电生理或受体证据。','Receptors and ionic conditions determine current and firing effects. Morphology offers clues; electrophysiological or receptor evidence may still be needed to establish function.')
],[P('教学读图：若看到前侧囊泡、明显厚的后侧 PSD 和圆囊泡，可描述为“符合经典 Gray I 特征，通常兴奋”。若问它是否一定使每个接收细胞发放，则不能只凭这张图保证。','Teaching interpretation: presynaptic vesicles, a thick PSD and round vesicles fit classical Gray I and usually excitation. The image alone cannot guarantee an AP in every receiving cell.'),P('比较题逐行对齐：I 与 II 都写对称性、囊泡形状和通常功能；不要一边只谈结构，另一边只谈速度。','Compare matching dimensions: symmetry, vesicle shape and usual function for both I and II. Do not compare structure on one side with speed on the other.')],P('“Axosomatic”是否直接说明用了哪种递质？','Does “axosomatic” directly identify the transmitter?'),P('没有。它只说明前侧轴突接到后侧胞体。递质身份和功能需要另外的分子与生理证据。','No. It specifies an axon-to-soma contact. Transmitter identity and function require additional molecular and physiological evidence.'),'synapse');

L('c5-t4',P('化学突触把前突触的电信号变成递质释放，再由突触后受体转成新的电或细胞内信号。Ca²⁺是释放的重要触发因素。','A chemical synapse converts a presynaptic electrical signal into transmitter release, then receptor activation into a postsynaptic electrical or intracellular signal. Ca²⁺ is an important release trigger.'),P('要在毫秒内完成交流，末梢不能等 AP 到来才制造和搬运一切。许多囊泡早已准备在释放位点，等待局部 Ca²⁺变化。','Millisecond communication cannot wait for all components to be made and transported after the AP arrives. Many vesicles are already prepared at release sites, awaiting local Ca²⁺ entry.'),[
 term('囊泡与胞吐','Vesicle and exocytosis','囊泡是装递质的小膜袋；它与突触前膜融合后把内容物释放到细胞外。','A vesicle is a small membrane-bound transmitter container; fusion with presynaptic membrane releases its contents outside.'),term('Docking／priming','Docking/priming','把囊泡定位到释放位点并准备好快速融合的步骤。','Positioning vesicles at release sites and preparing them for rapid fusion.'),term('SNARE 与 Ca²⁺传感器','SNAREs and Ca²⁺ sensors','SNARE 参与拉近并融合膜；synaptotagmin 等传感器检测 Ca²⁺并触发融合过程。','SNARE machinery brings membranes together for fusion; sensors such as synaptotagmin detect Ca²⁺ and trigger the process.')
],[
 step('提前准备','Prepare before the signal','囊泡可预先 docking/priming。v-SNARE 在囊泡膜，t-SNARE 在突触前靶膜，位置决定两张要融合的膜。','Vesicles can be docked and primed in advance. v-SNAREs are on vesicles and t-SNAREs on the presynaptic target membrane, locating the two membranes that fuse.'),
 step('AP 打开 Ca²⁺通道','The AP opens Ca²⁺ channels','AP 到达使末梢去极化，电压门控 Ca²⁺通道开放。Ca²⁺通常沿很大的电化学驱动力进入末梢。','The arriving AP depolarizes the terminal and opens voltage-gated Ca²⁺ channels. Ca²⁺ enters down its usually large electrochemical driving force.'),
 step('局部检测并触发融合','Local detection triggers fusion','释放位点附近形成短暂高 Ca²⁺微域；传感器响应，SNARE 机器完成膜融合与胞吐。不是全轴突 Ca²⁺必须先升到一样高。','A brief high-Ca²⁺ microdomain forms near release sites. Sensors respond and SNARE machinery completes fusion and exocytosis. The entire axon need not first reach the same Ca²⁺ level.'),
 step('递质到接收端','Transmitter reaches the receiver','递质扩散穿过狭窄间隙，与突触后受体结合。受体改变离子通路或胞内信号；快速性来自预先准备、空间接近和很短的传播距离。','Transmitter diffuses across the narrow cleft and binds postsynaptic receptors, changing ion pathways or intracellular signaling. Preparation, close spacing and short distances support speed.')
],[P('教学干预：若前突触 AP 仍正常，但短时阻断 Ca²⁺进入，典型诱发囊泡释放会减少。若直接在后侧施加正常递质仍有反应，说明接收端可工作，问题更可能在被绕过的前突触步骤。','Teaching intervention: blocking Ca²⁺ entry while preserving the presynaptic AP reduces typical evoked vesicular release. A preserved response to direct postsynaptic transmitter application supports a functioning receiver and an upstream defect in bypassed steps.'),P('这个结果还不能唯一锁定某一种 Ca²⁺通道或 SNARE；进一步定位要测 AP、Ca²⁺或释放量。','This does not uniquely identify a particular Ca²⁺ channel or SNARE; further localization requires AP, Ca²⁺ or release measurements.')],P('为什么“Ca²⁺很快在整个轴突积累”不是快速释放的好解释？','Why is rapid Ca²⁺ accumulation throughout the whole axon a poor explanation of fast release?'),P('释放只需要位点附近的局部高 Ca²⁺。通道与已经准备好的囊泡紧邻，减少扩散距离和等待时间；全轴突累积不是必要步骤。','Release needs high Ca²⁺ locally near the site. Channels adjacent to prepared vesicles minimize diffusion distance and waiting time; whole-axon accumulation is unnecessary.'),'synapse');

L('c5-t5',P('小分子递质和肽递质都能传递消息，但它们的生产地点、包装运输和释放条件常不同。','Small-molecule and peptide transmitters both carry messages, but their production, packaging, transport and release requirements often differ.'),P('区分两类能解释为什么有些信号一次刺激就容易释放，有些更需要持续活动。先比较生产和位置，再推 Ca²⁺条件，比只背分子名单更容易。','The distinction helps explain why some signals release readily with brief stimulation while others favor sustained activity. Compare production and location before inferring Ca²⁺ requirements.'),[
 term('小分子递质','Small-molecule transmitter','如 ACh、glutamate；许多可在末梢由已有酶合成，再装入囊泡。','Examples include ACh and glutamate; many are synthesized by terminal enzymes and then loaded into vesicles.'),term('肽前体与致密芯颗粒','Peptide precursor and dense-core granule','肽由较大前体加工而来，常装在显微镜下中心较致密的颗粒中。','Peptides are processed from larger precursors and commonly packaged in granules with dense-looking cores.'),term('顺向运输','Anterograde transport','从胞体向轴突末梢运输，常由 kinesin 沿微管完成。','Transport from soma toward axon terminal, commonly using kinesin along microtubules.')
],[
 step('许多小分子在末梢补给','Many small molecules are replenished at terminals','末梢酶把前体转成递质，转运体再把它装进囊泡。但酶是蛋白，仍通常需要在胞体制造并运来。','Terminal enzymes convert precursors into transmitter, which transporters load into vesicles. The enzymes are proteins and generally still require somatic production and transport.'),
 step('肽先在胞体生产包装','Peptides are produced and packaged in the soma','肽前体在粗面内质网合成，经 Golgi 加工并包装，随后颗粒沿轴突运输。不能把胞体依赖的肽补给当成末梢立即制造。','Peptide precursors are made in rough ER, processed and packaged through the Golgi, then transported along the axon. Somatic peptide supply is not immediate terminal production.'),
 step('位置决定对 Ca²⁺的需要','Location influences Ca²⁺ requirements','小透明囊泡常靠近 active zone 的 Ca²⁺通道；肽颗粒往往离局部通道更远。后者更常需要较广的 Ca²⁺升高。','Small clear vesicles are often close to active-zone Ca²⁺ channels; peptide granules are often farther away and more commonly require broader Ca²⁺ elevations.'),
 step('持续刺激改变释放组合','Sustained activity changes the release mix','持续高频活动可产生更广泛 Ca²⁺升高，较容易募集肽释放。小分子释放不因此必须停止，同一末梢可以共释放。','Sustained high-frequency activity can produce broader Ca²⁺ elevations and recruit peptide release. Small-molecule release need not stop; co-release can occur.')
],[P('教学情境：若希望某种突触信号更偏向在反复、持续刺激后出现，肽递质及较广 Ca²⁺需求是合理线索。单纯增加 active zone 数量并不直接解释这个持续刺激要求。','Teaching scenario: if a signal should emerge preferentially after repeated sustained stimulation, peptides and broader Ca²⁺ requirements are relevant clues. Merely increasing active-zone number does not directly explain that requirement.'),P('整理表时按相同四栏比较：在哪里合成、怎么包装、怎么到末梢、需要怎样的活动。ACh 是小分子，但不因此属于 monoamines。','Compare four matching columns: synthesis site, packaging, transport to terminal and activity requirements. ACh is a small molecule but is not therefore a monoamine.')],P('高频刺激引发肽释放，是否意味着此时只释放肽？','Does high-frequency peptide release imply that only peptides are released?'),P('不意味着。高频可额外募集肽颗粒，小分子囊泡仍可释放；关键是各类释放条件和位置，而不是把频率当成二选一开关。','No. High frequency can additionally recruit peptide granules while small-molecule vesicles still release. Frequency interacts with location and release requirements rather than acting as an exclusive binary switch.'));

L('c5-t6',P('递质释放后必须及时结束作用，细胞还要回收囊泡膜。清除化学信号和回收膜是两件不同的事。','After release, transmitter action must end and vesicle membrane must be retrieved. Chemical-signal clearance and membrane recycling are separate tasks.'),P('如果递质一直停在受体附近，接收细胞就难以区分前一次和后一次消息。终止机制帮助信号保持时间精度，回收机制则为后续释放准备材料。','Persistent transmitter near receptors makes successive messages difficult to distinguish. Termination preserves timing, while recycling prepares material for later release.'),[
 term('再摄取','Reuptake','通过细胞膜转运体把递质或相关原料从细胞外运回细胞。','Transporter-mediated recovery of transmitter or related precursor from outside into a cell.'),term('酶降解','Enzymatic degradation','酶改变递质的化学结构，使它不再以原分子继续作用。','Chemical modification of transmitter by enzymes, ending action of the original molecule.'),term('胞吞','Endocytosis','把胞吐后留在细胞表面的囊泡膜重新取回。','Retrieval of vesicle membrane left at the cell surface after exocytosis.')
],[
 step('递质离开受体附近','Remove transmitter from receptors','分子可以扩散离开，也可被神经元或胶质细胞的转运体摄取，或者被特定酶降解。不同递质使用的主要方式不完全相同。','Molecules can diffuse away, enter neurons/glia through transporters, or be degraded by specific enzymes. Different transmitters rely on different combinations.'),
 step('ACh 用水解终止','Terminate ACh through hydrolysis','AChE 把 ACh 水解成 acetate 和 choline。AChE 不是受体，也不是把 ACh 装进囊泡的转运体；它改变的是分子本身。','AChE hydrolyzes ACh into acetate and choline. It is neither a receptor nor a vesicular transporter: it chemically changes the molecule.'),
 step('回收原料再合成','Recover precursor for resynthesis','choline 被摄取回末梢，ChAT 用它和 acetyl CoA 再合成 ACh。因此“choline 再摄取”和“完整 ACh 再摄取”不能混写。','Choline is taken back into the terminal and ChAT combines it with acetyl CoA to remake ACh. Choline uptake is not intact-ACh uptake.'),
 step('另外处理囊泡膜','Retrieve membrane separately','囊泡已经融合到表面，胞吞回收其膜，之后重新装填。不要把这一步写成所有自由递质都被胞吞吸回。','After fusion, endocytosis retrieves vesicle membrane for later refilling. This is not uptake of all free transmitter by engulfment.')
],[P('教学对比：抑制 AChE 会减慢 ACh 水解，可能延长受体暴露；抑制 ChAT 则减少新 ACh 合成。虽然两个名字都含 ACh，它们作用在循环的不同位置。','Teaching comparison: AChE inhibition slows hydrolysis and can prolong receptor exposure; ChAT inhibition reduces new ACh synthesis. Similar names do not mean the enzymes act at the same cycle stage.'),P('把对象分别写清：清除的是递质信号，回收的原料是 choline，胞吞回收的是膜。这样能避免“reuptake”一词掩盖不同机制。','Name each object: terminate transmitter signaling, recover choline precursor, and retrieve membrane by endocytosis. This prevents the word reuptake from hiding distinct mechanisms.')],P('胞吞很正常，是否就说明递质已经被有效清除？','Does normal endocytosis prove that transmitter has been effectively cleared?'),P('不能。膜回收正常不证明细胞外递质的转运或降解正常。要分别测膜回收与递质暴露，才知道哪个步骤存在问题。','No. Normal membrane retrieval does not establish normal extracellular uptake or degradation. Separate measurements are needed to identify which process is impaired.'),'cycle');

L('c5-t7',P('递质像一条消息，受体决定细胞怎样读它。相同递质可以通过不同受体产生不同甚至相反的反应。','A transmitter carries a message; receptors determine how the cell interprets it. The same transmitter can produce different or opposite responses through different receptors.'),P('不能只背“ACh 兴奋”或“GABA 永远超极化”。先问受体是哪一类、改变什么通路，再看离子条件与细胞原来的状态。','Avoid memorizing “ACh excites” or “GABA always hyperpolarizes.” Identify the receptor and pathway first, then consider ionic conditions and the cell’s initial state.'),[
 term('离子型受体','Ionotropic receptor','受体本身就是递质门控离子通道，结合可直接改变通道电导。','A receptor that is itself a transmitter-gated channel, directly changing conductance on activation.'),term('代谢型受体','Metabotropic receptor','通常通过 G 蛋白与效应器间接调节通道或细胞内反应。','A receptor commonly using G proteins and effectors to regulate channels or intracellular reactions indirectly.'),term('反转电位','Reversal potential','该受体通路净电流为零时的膜电位；混合离子通道不必等于某一个离子的 E。','The voltage at which net current through that receptor pathway is zero; for mixed-ion channels it need not equal one ion’s E.')
],[
 step('先识别受体','Identify the receptor','nAChR 是骨骼肌常见的离子型 ACh 受体；心脏减速主要涉及 muscarinic M2 型代谢型受体。递质相同，接收装置不同。','Skeletal-muscle nAChRs are ionotropic ACh receptors; cardiac slowing mainly involves metabotropic M2 muscarinic receptors. The transmitter is the same but the receiver differs.'),
 step('再追到离子或效应器','Trace the channel or effector','nAChR 开放阳离子通路，常见静息条件下净内向电流使终板去极化。心脏 M2 通路可经 G 蛋白提高 K⁺通透性并改变起搏活动。','nAChRs open cation pathways, producing depolarizing inward current under common resting conditions. Cardiac M2 signaling can increase K⁺ permeability through G proteins and alter pacemaker activity.'),
 step('比较 Vm 与反转电位','Compare Vm with reversal potential','开放被动通路通常把 Vm 拉向其反转电位。Cl⁻通路若反转点近静息，可能电压变化很小却降低输入电阻，产生分流抑制。','Opening a passive pathway generally draws Vm toward its reversal potential. A Cl⁻ pathway reversing near rest may cause little voltage change while lowering input resistance and shunting excitation.'),
 step('把受体激活与细胞效应分开','Separate receptor activation from cellular effect','激动剂指激活受体，不保证细胞兴奋。代谢型信号通常较慢且持续较久，但具体方向和速度仍由亚型、效应器和条件决定。','Agonism means receptor activation, not guaranteed cellular excitation. Metabotropic effects are often slower and longer-lasting, but subtype, effector and conditions determine the response.')
],[P('教学比较：给骨骼肌与心脏相同的 ACh 消息，前者可出现终板去极化，后者可减慢节律。这不是 ACh 换了一种身份，而是受体和下游通路不同。','Teaching comparison: ACh can depolarize a skeletal-muscle end plate while slowing the heart. The transmitter has not changed identity; receptors and downstream pathways differ.'),P('答题可固定使用“受体亚型→通道／效应器→电导变化→Vm 或发放概率”的顺序。递质名只完成了这条链的起点。','Use receptor subtype → channel/effector → conductance change → Vm or firing probability. Naming the transmitter only starts the explanation.')],P('为什么激动一个受体也可能降低细胞活动？','Why can activating a receptor reduce cellular activity?'),P('该受体可能连接增加 K⁺电导等抑制性通路。激动／拮抗描述受体层面，兴奋／抑制描述细胞或回路结果，二者不能直接互换。','The receptor may activate an inhibitory pathway such as increased K⁺ conductance. Agonism/antagonism describe receptor action, whereas excitation/inhibition describe cellular or circuit outcomes.'));

L('c5-t8',P('一个小输入往往不足以让细胞发放。多个 PSP 在时间和空间上重叠，才共同决定轴突初始段是否达到阈值。','One small input often cannot trigger firing. PSPs overlapping in time and space jointly determine whether the axon initial segment reaches threshold.'),P('神经元通常同时接收许多来源的消息。整合就是让这些输入的大小、位置、到达时间和抑制作用共同影响输出，而不是简单数收到多少个 AP。','Neurons typically receive many messages. Integration combines their strength, location, timing and inhibition rather than merely counting incoming APs.'),[
 term('空间总和','Spatial summation','不同突触产生的 PSP 在时间上重叠。','Temporal overlap of PSPs generated at different synapses.'),term('时间总和','Temporal summation','前一次 PSP 尚未消退，同一输入再次引起 PSP。','Repeated activation of an input before its previous PSP has decayed.'),term('轴突初始段','Axon initial segment','轴突靠近胞体的区域，常有较高 Na⁺通道密度，是通常的 AP 起始位置。','The proximal axon region, commonly rich in Na⁺ channels and the usual AP initiation site.')
],[
 step('一个输入产生分级反应','One input produces a graded response','单个 CNS 前突触 AP 可以使受体开放并产生一个 EPSP。EPSP 很小，不够触发后侧 AP，也仍然是真实的突触传递。','One presynaptic CNS AP can activate receptors and produce an EPSP. A small EPSP insufficient for a postsynaptic AP still represents real transmission.'),
 step('不同地点合起来','Combine different locations','多个突触的 PSP 传播到整合区时若重叠，就产生空间总和。远端输入可能因衰减，在起始段保留得较少。','PSPs from different synapses spatially summate if they overlap at the integration region. Distal inputs may retain less amplitude after attenuation.'),
 step('同一输入赶在消退前再来','Repeat input before decay','若前一个 PSP 尚未回到基线，下一次又到达，变化可以重叠形成时间总和。间隔太长则难以有效重叠。','If another PSP arrives before the previous one returns to baseline, temporal overlap can build a larger response. Widely separated inputs summate less effectively.'),
 step('与抑制共同决定阈值','Include inhibition and threshold','抑制输入可改变电压或电导，削弱兴奋输入的效果。最终由初始段的膜状态是否启动 Na⁺再生过程，决定是否产生下一次 AP。','Inhibition can change voltage or conductance and weaken excitation. The initial segment’s ability to initiate regenerative Na⁺ activity ultimately determines the next AP.')
],[P('教学近似：起始段静息 −65 mV，示例阈值 −55 mV。两个同时到达、各贡献约 6 mV 的 EPSP，在简化线性相加模型中可把 Vm 推到约 −53 mV；若相隔太久，就可能各自只有一次小变化。','Teaching approximation: rest is −65 mV and illustrative threshold −55 mV. Two overlapping EPSPs contributing about 6 mV each can reach roughly −53 mV in a simplified linear model. If widely separated, they may remain small individual responses.'),P('真实突触的电导、反转电位与膜状态会使相加偏离简单算术。例子用于理解重叠和阈值，不是保证任意两个 EPSP 都精确相加。','Real conductances, reversal potentials and membrane state can make summation nonlinear. The example illustrates overlap and threshold, not exact addition of arbitrary EPSPs.')],P('一个后侧细胞没有发 AP，能否认定它没有收到兴奋性输入？','Does absence of a postsynaptic AP prove absence of excitatory input?'),P('不能。它可能已有 EPSP，只是输入太小、衰减太多、时间不重叠或被抑制。需要区分输入存在、局部电位变化和输出发放。','No. An EPSP may be too small, attenuated, poorly timed or opposed by inhibition. Distinguish input, local voltage response and output firing.'));

L('c5-t9',P('小的兴奋性电压变化会随距离变弱。分流抑制让同样的兴奋输入产生更小的电压变化，即使静息电位几乎没有下降。','A small excitatory voltage change weakens with distance. Shunting inhibition makes the same excitatory input produce a smaller voltage response even with little resting hyperpolarization.'),P('接收细胞不只需要“得到一些正电流”，还要让电压变化足够大并传到起始段。如果新开放的通路增加膜电导，输入电流对 Vm 的影响就可能变小。','The receiver needs a voltage change large enough to influence the initiation zone, not merely some positive current. Opening additional pathways raises conductance and can reduce the effect of input on Vm.'),[
 term('EPSP','Excitatory postsynaptic potential','让后侧细胞更容易发放的局部分级电位，常表现为去极化。','A local graded postsynaptic response favoring firing, commonly depolarizing.'),term('输入电阻','Input resistance','在给定条件下，同样注入电流能造成多大电压变化的尺度。','A measure of how much voltage changes for a given injected current under specified conditions.'),term('长度常数 λ','Length constant λ','被动电压变化降到初始约 37% 时的距离；更大表示衰减较慢。','The distance at which a passive voltage change falls to about 37% of its initial value; larger means slower attenuation.')
],[
 step('先理解正常的衰减','First understand passive attenuation','兴奋性电位沿树突或其他被动膜传播时，电流会经膜通路分流，沿途电压变化逐渐变小。它不像 AP 那样每段都再生。','As an excitatory voltage spreads through passive membrane, membrane pathways divert current and the voltage response shrinks with distance. It does not regenerate at each segment like an AP.'),
 step('开放近静息反转点的通路','Open a pathway reversing near rest','若 E_Cl 接近静息，开放 Cl⁻通路对静息 Vm 的直接影响可能很小。但可通过的通路增多，使膜电导 g_m 增大，电阻降低。','If E_Cl is near rest, opening Cl⁻ pathways can have little direct resting-voltage effect. More conducting pathways nevertheless increase g_m and lower resistance.'),
 step('同样电流产生更小 ΔV','The same current produces a smaller ΔV','在固定注入电流的小信号模型中，ΔV≈I×R。R 降低，所以兴奋引起的电压变化变小，更不容易把起始段推到阈值。','In a small-signal model with fixed injected current, ΔV≈I×R. Lower R therefore reduces the excitatory voltage change, making threshold less likely.'),
 step('最后引入传播公式','Now introduce the spread equations','ΔV(x)=ΔV(0)e^(−x/λ)，x 和 λ 使用相同长度单位。用每单位长度电阻时 λ=√(r_m/r_i)；r_m 降低会减小 λ，使同样距离衰减更多。更粗直径、髓鞘和细胞内电阻率也可影响传播。','ΔV(x)=ΔV(0)e^(−x/λ), with x and λ in matching length units. For resistances per unit length, λ=√(r_m/r_i). Lower r_m reduces λ and increases attenuation over the same distance. Diameter, myelin and intracellular resistivity also influence spread.')
],[P('教学计算一：固定注入电流 I=0.10 nA，输入电阻 R=100 MΩ，则 ΔV=10 mV。开放额外通路后 R=50 MΩ，同样电流只有 ΔV=5 mV。静息仍可约 −65 mV，但输入带来的提升明显变小。','Teaching calculation 1: I=0.10 nA and R=100 MΩ give ΔV=10 mV. If added pathways lower R to 50 MΩ, the same current gives 5 mV. Rest can remain near −65 mV while the input-induced rise becomes smaller.'),P('教学计算二：初始变化 10 mV，x=1 mm、λ=1 mm，则 ΔV=10e⁻¹≈3.68 mV。λ 描述距离衰减，不是 AP 频率，也不是到某一点突然归零的距离。','Teaching calculation 2: with an initial 10 mV, x=1 mm and λ=1 mm, ΔV=10e⁻¹≈3.68 mV. λ describes spatial attenuation, not AP frequency or a distance where voltage suddenly becomes zero.'),P('“漏水容器多开一个出口”可帮助想象分流，但真实解释仍是膜电导、驱动力和电压响应；并不是所有 Cl⁻通道在所有条件下都使膜超极化。','An extra outlet in a leaky container can suggest shunting, but the actual explanation uses conductance, driving force and voltage response. Cl⁻ channels do not hyperpolarize under every condition.')],P('若静息 Vm 几乎没变，怎样证明这次通道开放仍有抑制效果？','If resting Vm barely changes, how can channel opening still be inhibitory?'),P('比较相同兴奋输入前后的电压响应或发放概率。若电导增加、输入电阻下降，同样输入产生更小响应且更难达阈，就支持分流抑制；不需要先出现很大的超极化。','Compare voltage response or firing probability for matched excitatory input. Higher conductance and lower input resistance can give a smaller response and reduced threshold crossing without a large preceding hyperpolarization.'),'decay');

L('c5-t10',P('神经肌肉接头 NMJ 让一次运动神经 AP 通常可靠地引发一次肌肉 AP。安全系数是终板去极化超过触发需要的余量。','The neuromuscular junction usually turns a motor-neuron AP reliably into a muscle AP. Its safety factor is the margin by which end-plate depolarization exceeds the firing requirement.'),P('中枢神经元常需要很多小输入相加，而肌肉接头通常需要单次指令就可靠传递。它通过较多释放和强接收结构提供余量，并及时结束信号。','CNS neurons often integrate many small inputs, whereas the NMJ normally needs reliable transmission of a single command. Abundant release, strong receiving structures and prompt termination support this function.'),[
 term('终板电位 EPP','End-plate potential, EPP','ACh 激活肌肉 nAChR 产生的分级去极化，不是肌肉 AP 本身。','The graded depolarization produced by ACh at muscle nAChRs, not the muscle AP itself.'),term('安全系数','Safety factor','正常 EPP 高于产生肌肉 AP 所需去极化的余量。','The margin by which a normal EPP exceeds depolarization needed for a muscle AP.'),term('微终板电位','Miniature end-plate potential','自发释放一个囊泡时产生的小分级响应，体现量子释放。','A small graded response to spontaneous release of one vesicle, illustrating quantal release.')
],[
 step('多位点释放足够 ACh','Release ample ACh at multiple sites','较大接触区和多个 active zone 支持一次神经 AP 释放许多囊泡，因此单次化学信号较强。','A large contact region and multiple active zones support release of many vesicles after one nerve AP, producing a substantial chemical signal.'),
 step('受体与皱褶增强接收','Receptors and folds support reception','密集 nAChR 和突触后膜皱褶提供有效接收结构。ACh 结合后开放阳离子通路，常见静息条件下产生去极化 EPP。','Dense nAChRs and postsynaptic folds support reception. ACh opens cation pathways and produces a depolarizing EPP under common resting conditions.'),
 step('EPP 留出阈值余量','The EPP provides a threshold margin','EPP 通常大于触发肌肉 AP 的最低去极化需求，所以小幅波动仍可能成功。这个余量来自释放和接收机制，不是运动神经 AP 振幅特别巨大。','The EPP usually exceeds the minimum depolarization needed for a muscle AP, so modest variation may still permit success. The margin comes from release and reception, not an unusually large motor-neuron AP.'),
 step('及时清除，准备下一次','Terminate promptly for the next response','AChE 水解 ACh，减少持续受体暴露，支持肌肉及时恢复并响应下一次指令。安全系数描述正常生理高可靠性，不是毒素或疾病条件下永不失败。','AChE hydrolyzes ACh, limiting persistent receptor exposure and supporting the next response. Safety factor describes normal physiological reliability, not guaranteed success under toxin exposure or disease.')
],[P('教学近似：若触发肌肉 AP 需去极化 15 mV，正常 EPP 为 30 mV，就有 15 mV 余量。若释放下降使 EPP 只有 10 mV，尽管神经 AP 正常，肌肉仍可能不发放。数值仅说明余量概念。','Teaching approximation: if firing requires 15 mV depolarization and the normal EPP is 30 mV, there is a 15 mV margin. Reduced release giving only 10 mV can fail despite a normal nerve AP. These numbers illustrate the margin concept.'),P('FRQ 要把结构与功能配对：多 active zone→多囊泡释放；密集受体／皱褶→较大接收响应；AChE→快速终止与重复传递。','In an FRQ, pair structure with function: many active zones → multivesicular release; dense receptors/folds → strong response; AChE → prompt termination and repeated transmission.')],P('为什么“AChE 多”不能单独解释 EPP 很大？','Why does abundant AChE alone not explain a large EPP?'),P('AChE 负责降解和终止，并不合成 ACh，也不直接开放 nAChR。大 EPP 主要由足够释放与有效受体响应产生；AChE 支持下一次准确响应。','AChE degrades and terminates the signal; it neither synthesizes ACh nor directly opens nAChRs. Ample release and effective receptor activation generate the large EPP, while AChE supports accurate subsequent responses.'));

L('c6-t1',P('发现细胞里有一种化学物质，还不足以叫它“这里的神经递质”。要证明它由发送端准备、在活动时释放，并能解释接收端反应。','Finding a chemical inside a cell is not enough to identify it as the transmitter at that synapse. Evidence must connect presynaptic preparation, activity-dependent release and the receiving response.'),P('一个分子可能只是代谢原料，或存在却没有被这个突触使用。三条判据分别回答“从哪里来”“何时出去”“出去后做什么”。','A molecule may be a metabolic substrate or present without serving this synapse. The three criteria ask where it comes from, when it leaves, and what it does afterward.'),[
 term('合成与储存','Synthesis and storage','发送细胞能够制造并保存候选递质。','The sending cell can produce and store the candidate transmitter.'),term('外源施加','Exogenous application','实验者把候选物直接给到接收细胞，用来比较正常释放的作用。','Experimental delivery of the candidate to the receiver for comparison with normal release.'),term('模拟反应','Mimicry','候选物引起与内源传递相符的响应，而不只是任意改变电位。','A response matching endogenous transmission, not merely any voltage change.')
],[
 step('确认发送端具备它','Establish presynaptic presence','用分子或酶定位等证据支持突触前合成和储存。仅在旁边某颗细胞发现分子，不等于所研究发送端使用它。','Localization of the molecule or relevant enzymes can support presynaptic synthesis/storage. Finding it in a nearby cell does not establish its use by the studied sender.'),
 step('把活动与释放连起来','Link activity to release','比较刺激前后候选物的细胞外变化，并检验典型囊泡释放的 Ca²⁺依赖。需要控制样本活性，避免把组织受损误当作释放机制。','Compare extracellular candidate before and after stimulation and test Ca²⁺ dependence of typical vesicular release. Control viability to avoid confusing tissue damage with release mechanisms.'),
 step('把候选物与接收反应连起来','Link candidate to the receiving response','局部外源给药应模仿正常内源传递的反应。相同受体拮抗剂对两种反应都有相应阻断，可进一步支持共同通路。','Local external application should mimic the endogenous response. Corresponding blockade of both by the same receptor antagonist further supports a shared pathway.'),
 step('综合证据，而不是凑方法名','Combine evidence rather than count methods','三种染色法若都只定位分子，仍没有回答释放和功能。这里是经典囊泡递质判据；NO 等非典型信号不必符合相同储存方式。','Three staining methods still address only localization, not release and function. These are classical vesicular-transmitter criteria; nonclassical signals such as NO need not use identical storage mechanisms.')
],[P('教学情境：X 的合成酶染色阳性，只支持细胞有相关合成能力；再测得刺激依赖释放，补上释放证据；最后外源 X 模仿突触反应且被同一拮抗剂阻断，才形成较完整证据链。','Teaching scenario: positive staining for an X-synthetic enzyme supports synthetic capacity. Stimulation-dependent release adds release evidence. External X mimicking the synaptic response with matched antagonist sensitivity completes a stronger chain.'),P('答题中，每条判据后接“怎么测、测到什么才支持它”，比只写 IHC、FISH、刺激三个方法名更清晰。','For each criterion, state the measurement and the supporting result rather than listing IHC, FISH and stimulation as three method names.')],P('如果 X 能使细胞去极化，是否就完成了递质鉴定？','If X depolarizes a cell, is transmitter identification complete?'),P('没有。任意去极化不证明前突触合成、活动时释放或与内源反应相同。必须把这些不同环节分别验证。','No. Arbitrary depolarization does not establish presynaptic synthesis, activity-dependent release or correspondence with the endogenous response. Test those links separately.'));

L('c6-t2',P('IHC 用抗体寻找分子或蛋白；FISH 用互补探针寻找 mRNA。二者提供位置证据，但所寻找的对象不同。','IHC uses antibodies to locate molecules/proteins; FISH uses complementary probes to locate mRNA. Both provide localization evidence, but their targets differ.'),P('递质有时难以直接检测，研究者会寻找制造它的酶或酶的 mRNA。这类似寻找生产工具或制作说明，但找到它们不等于亲眼看到一次递质释放。','When direct transmitter detection is difficult, researchers can look for its synthetic enzyme or enzyme mRNA. Finding production machinery or instructions supports capacity, not direct observation of release.'),[
 term('抗原与抗体','Antigen and antibody','抗体能够特异识别某些分子结构；被识别的靶标是抗原。','An antibody specifically recognizes particular molecular structures; its recognized target is the antigen.'),term('mRNA','Messenger RNA','用于制造蛋白的转录本；小分子递质本身不是直接从 mRNA 翻译出来的。','A transcript used to make a protein; a small-molecule transmitter is not itself directly translated from mRNA.'),term('互补探针','Complementary probe','按碱基互补识别目标核酸序列的标记核酸。','A labeled nucleic acid recognizing a target sequence through complementary base pairing.')
],[
 step('IHC：抗体找到靶标','IHC: an antibody recognizes its target','抗体结合候选递质相关抗原或合成酶，再用可检测标签显示位置。例如 ChAT 蛋白定位可支持 cholinergic 表型。','An antibody binds a transmitter-related antigen or synthetic enzyme, and a detectable label reveals location. ChAT localization, for example, can support a cholinergic phenotype.'),
 step('FISH：探针找到转录本','FISH: a probe recognizes a transcript','探针与相关 mRNA 杂交，荧光信号显示其位置。若研究 ACh，可找 ChAT 的 mRNA，而不是虚构一个直接编码 ACh 小分子的 mRNA。','A probe hybridizes to relevant mRNA and fluorescence shows its location. For ACh, a ChAT transcript can be targeted; there is no mRNA directly encoding the small ACh molecule.'),
 step('标签不能混名','Name the detection method accurately','FISH 中 F 指 fluorescent。放射性探针和放射自显影可用于另一种 ISH，但不能因为都使用探针就叫 FISH。','F in FISH means fluorescent. Radioactive probes and autoradiography can be used in another form of ISH, but are not FISH simply because they use probes.'),
 step('用对照限定推断','Use controls and limit inference','验证抗体／探针特异性，设置已知阳性与阴性对照。TH 阳性支持儿茶酚胺合成相关表型，却不能仅凭它区分所有 DA、NE 或 E 细胞，更不能单独证明释放。','Validate antibody/probe specificity and use known positive/negative controls. TH positivity supports a catecholamine-related phenotype but does not alone distinguish every DA, NE or epinephrine cell or prove release.')
],[P('教学对比：A 图标记 ChAT 蛋白，属于 IHC 型定位；B 图标记 ChAT mRNA，属于相关原位杂交。两图都可能提示同类细胞，但一个看到工具，一个看到制造工具的转录本。','Teaching comparison: image A labels ChAT protein, an IHC-type localization; image B labels ChAT mRNA by in situ hybridization. Both may identify related cells, but one detects machinery and the other its transcript.'),P('在 FRQ 写出靶标、结合原理、标签和读数，再补“不能单独证明刺激依赖释放”，就把方法和推断边界连接起来。','An FRQ should name the target, recognition principle, label and readout, then state that localization alone does not prove stimulation-dependent release.')],P('抗体识别 mRNA 的互补碱基序列，这句话哪里错？','What is wrong with saying that an antibody recognizes complementary mRNA bases?'),P('它混合了两种识别机制。抗体识别抗原结构；核酸探针通过碱基互补识别 mRNA。方法名、靶标和结合原理必须对应。','It combines different recognition mechanisms. Antibodies recognize antigen structures; nucleic-acid probes recognize mRNA through complementarity. Match method, target and binding principle.'));

L('c6-t3',P('释放实验问“刺激后候选物是否被释放”；模拟实验问“直接给候选物能否重现正常接收反应”。它们回答不同问题。','A release assay asks whether stimulation releases a candidate; a mimicry experiment asks whether direct application reproduces the normal receiving response. They answer different questions.'),P('实验设计需要把操作、读数、对照和推断连成链。只写“刺激后有变化”，还不清楚变化来自正常传递、组织受损还是非特异作用。','Experimental design must connect manipulation, readout, control and inference. “Something changed after stimulation” does not distinguish normal transmission, tissue damage or nonspecific effects.'),[
 term('基线与对照','Baseline and control','基线是操作前状态；对照帮助排除操作之外的解释。','Baseline is the pre-manipulation state; a control helps exclude alternative explanations.'),term('高 K⁺去极化','High-K⁺ depolarization','提高外 K⁺可使 E_K 较不负并促使细胞去极化；不是单细胞特异刺激。','Elevated extracellular K⁺ makes E_K less negative and can depolarize cells; it is not single-cell-selective stimulation.'),term('局部给药','Local application','可用微离子电泳的电流驱动或压力喷射等方式施加候选物。','Delivery by methods such as current-driven microiontophoresis or pressure ejection.')
],[
 step('保持样本可用并测基线','Maintain viability and measure baseline','切片需要适宜氧、营养和温度。记录基线释放量或电反应，再进行匹配操作，才能解释之后的差异。','Maintain appropriate oxygen, nutrients and temperature. Record baseline release or electrical response before matched manipulations so later differences can be interpreted.'),
 step('刺激并测候选释放','Stimulate and measure release','比较刺激组与未刺激组的候选物释放。高 K⁺可以促进去极化，但若用了高 K⁺，推断范围不能写成只刺激了一颗指定细胞。','Compare candidate release in stimulated and unstimulated conditions. High K⁺ can promote depolarization, but does not establish stimulation of only one specified cell.'),
 step('检验 Ca²⁺依赖','Test Ca²⁺ dependence','减少 Ca²⁺进入后释放若减少，支持典型诱发释放的 Ca²⁺依赖。需要确认组织仍有活性，而不是把死亡引起的无反应当成证据。','Reduced release after reducing Ca²⁺ entry supports Ca²⁺ dependence of typical evoked release. Confirm viability rather than treating loss of response in dead tissue as evidence.'),
 step('比较外源与内源反应','Compare external and endogenous responses','局部给候选物并记录后侧响应，与正常前突触刺激比较。再用同一受体拮抗剂比较两者，检验是否符合共同通路。','Apply the candidate locally and compare the postsynaptic response with presynaptic stimulation. Test the same receptor antagonist against both to examine a shared pathway.')
],[P('教学情境：刺激使 X 释放增加；减少 Ca²⁺进入使这项增加变小且组织仍活；外源 X 模仿内源 EPSP，两者均被同一拮抗剂阻断。每一项分别支持释放、Ca²⁺依赖或功能一致性。','Teaching scenario: stimulation increases X release; reduced Ca²⁺ entry diminishes that increase while tissue remains viable; external X mimics the endogenous EPSP and both are blocked by the same antagonist. These findings separately support release, Ca²⁺ dependence and functional consistency.'),P('它们仍需与突触前合成和储存证据合并；不能因为某一个实验成功就省掉其余判据。','Combine these results with presynaptic synthesis/storage evidence; one successful experiment does not eliminate the other criteria.')],P('为什么撤掉营养后没有释放，不足以证明“释放依赖 Ca²⁺”？','Why does absent release after nutrient withdrawal not prove Ca²⁺ dependence?'),P('操作改变的是营养与组织活性，可能同时破坏许多过程，没有特异检验 Ca²⁺作用。要操纵相关 Ca²⁺条件并控制活性，才有相应因果解释。','Nutrient withdrawal changes viability and can disrupt many processes without specifically testing Ca²⁺. Manipulate relevant Ca²⁺ conditions while controlling viability to support that causal inference.'));

L('c6-t4',P('激动剂激活受体；拮抗剂减少激动剂引起的受体激活。这两个词描述受体作用，不直接等于细胞兴奋或抑制。','An agonist activates a receptor; an antagonist reduces activation by an agonist. These terms describe receptor action, not automatically cellular excitation or inhibition.'),P('药物可能直接作用于受体，也可能改变合成或清除。先定位作用对象，才能理解同样“反应变大”可能来自完全不同的原因。','A drug can act at a receptor or alter synthesis or clearance. Locating its target explains why a larger response can arise through very different mechanisms.'),[
 term('Agonist','Agonist','结合并激活相应受体的配体。','A ligand that binds and activates the relevant receptor.'),term('Antagonist','Antagonist','阻止或减少激动剂作用、而不产生同样激活的配体。','A ligand that prevents or reduces agonist action without producing the same activation.'),term('受体亚型','Receptor subtype','识别和信号方式有差别的受体类型；不能只凭递质名字互换。','A receptor type with distinct recognition/signaling properties, not interchangeable merely because it recognizes the same transmitter.')
],[
 step('先问有没有激活','Ask whether the receptor is activated','只检测到结合位点还不能判断 agonist。需要功能证据，说明结合后是否启动受体通路。作用时间长短不是定义。','Binding-site detection alone does not establish agonism. Functional evidence must show whether binding activates the pathway. Duration is not the definition.'),
 step('把例子和受体配对','Match examples to their receptors','nicotine／curare 是 nAChR 的经典激动／拮抗例子；muscarine／atropine 对应 muscarinic 受体。不要把不同亚型的例子随意互换。','Nicotine/curare are classic nAChR agonist/antagonist examples; muscarine/atropine correspond to muscarinic receptors. Do not interchange examples across subtypes.'),
 step('再推细胞结果','Then infer the cellular result','如果受体激活增加抑制性通路，agonist 也可降低活动。阻断这样的受体又可能解除抑制，因此 antagonist 不保证产生 IPSP。','An agonist can reduce activity if its receptor activates an inhibitory pathway. Blocking that receptor can disinhibit, so antagonism does not guarantee an IPSP.'),
 step('归类常考受体','Classify common receptor families','AMPA、NMDA、kainate 属于 glutamate 离子型受体；GABA_A 为离子型，GABA_B 为代谢型。名称对应关系要和功能分析一起掌握。','AMPA, NMDA and kainate are ionotropic glutamate receptors; GABA_A is ionotropic and GABA_B metabotropic. Learn family identity together with functional reasoning.')
],[P('教学情境：某药直接结合并激活 dopamine receptor，可称该受体 agonist。另一药仅阻断 dopamine 再摄取，使外侧 dopamine 停留更久，不因此成为直接受体 agonist。','Teaching scenario: a drug directly activating a dopamine receptor is an agonist at that receptor. A different drug only blocking dopamine uptake prolongs extracellular exposure without thereby becoming a direct receptor agonist.'),P('答题写“在哪个受体、什么作用、通过哪个通路产生结果”，比单写“兴奋剂／抑制剂”更准确。','Specify which receptor, what action and which downstream pathway rather than only calling the drug excitatory or inhibitory.')],P('拮抗一个抑制性受体后，为什么回路可能更活跃？','Why can blocking an inhibitory receptor make a circuit more active?'),P('因为原本降低活动的作用被削弱，即解除抑制。受体激活被减少与回路活动被减少不是同一件事。','The original activity-reducing action is weakened: disinhibition. Reducing receptor activation is not necessarily reducing circuit activity.'));

L('c6-t5',P('ACh 的循环包括取回 choline、合成 ACh、装入囊泡、释放、受体作用和水解。每一步由不同工具负责。','The ACh cycle includes choline uptake, ACh synthesis, vesicular loading, release, receptor action and hydrolysis. Different tools carry out different steps.'),P('ChAT、AChE 和 VAChT 名字相近，容易混淆。把它们放到循环地图上，就能预测阻断某一步后哪里变多、哪里变少。','ChAT, AChE and VAChT have similar names but different roles. Placing them on a cycle map helps predict what increases or decreases after an intervention.'),[
 term('ChAT','Choline acetyltransferase','合成酶：把 choline 与 acetyl CoA 转为 ACh 与 CoA。','The synthetic enzyme combining choline and acetyl CoA to form ACh and CoA.'),term('CHT 与 VAChT','CHT and VAChT','前者在细胞膜摄取 choline；后者在囊泡膜装填 ACh。','CHT takes up choline across the cell membrane; VAChT loads ACh across the vesicle membrane.'),term('AChE','Acetylcholinesterase','水解酶：把 ACh 分解成 acetate 和 choline。','The enzyme hydrolyzing ACh into acetate and choline.')
],[
 step('取得原料','Obtain the precursor','高亲和、Na⁺依赖的 choline 摄取为合成供料，是课堂强调的限速供给环节。产物 ACh 的量不是它自己的前体供给。','High-affinity Na⁺-dependent choline uptake supplies synthesis and is the classroom-emphasized limiting supply step. ACh product amount is not its own precursor supply.'),
 step('合成并装囊泡','Synthesize and load vesicles','ChAT 催化 acetyl CoA+choline→ACh+CoA。VAChT 再借囊泡质子梯度把 ACh 装进去；合成和装填是先后两个过程。','ChAT catalyzes acetyl CoA+choline→ACh+CoA. VAChT then uses the vesicular proton gradient to load ACh. Synthesis and loading are distinct consecutive processes.'),
 step('释放后作用于受体','Release and receptor action','AP 引起局部 Ca²⁺进入，囊泡融合释放 ACh。受体亚型决定后侧反应，不能由 ACh 名字直接推定一定兴奋。','AP-driven local Ca²⁺ entry triggers vesicle fusion and ACh release. Receptor subtype determines the receiving response; ACh identity alone does not guarantee excitation.'),
 step('水解并回收原料','Hydrolyze and recover precursor','AChE 快速水解 ACh，choline 被再摄取用于下一轮。经典循环回收的是 choline，不是把完整 ACh 当成主要再摄取底物。','AChE rapidly hydrolyzes ACh and choline is recovered for another cycle. The classic cycle chiefly recovers choline, not intact ACh.')
],[P('教学定位：抑制 ChAT→新合成减少；阻断 VAChT→囊泡装填减少，即使细胞质还有 ACh；抑制 AChE→水解变慢，受体暴露可能延长。','Teaching localization: inhibit ChAT → less new synthesis; block VAChT → less vesicular loading even if cytoplasmic ACh remains; inhibit AChE → slower hydrolysis and potentially longer receptor exposure.'),P('新烟碱类主要作用于昆虫 nAChRs，不能把名称中的“烟碱”或笔记简写误当成 AChE 抑制机制。原评分表的 Amount of ACh 也应改成相关 choline 供给。','Neonicotinoids mainly act at insect nAChRs; their name or shorthand does not make them AChE inhibitors. The supplied marking table’s “Amount of ACh” should likewise be corrected to the relevant choline supply.')],P('细胞膜 choline 转运体和囊泡 ACh 转运体为什么不能互换？','Why are plasma-membrane choline and vesicular ACh transporters not interchangeable?'),P('它们跨不同膜、运不同底物、处在不同步骤，也使用不同能量耦联：CHT 提供合成原料，VAChT 决定囊泡装填。','They cross different membranes, carry different substrates, occupy different steps and use different energy coupling. CHT supplies synthesis; VAChT loads vesicles.'),'cycle');

L('c6-t6',P('Dopamine、norepinephrine 和 epinephrine 是同一合成路径上的儿茶酚胺。每一步需要特定酶，不能跳过中间物 L-DOPA。','Dopamine, norepinephrine and epinephrine are catecholamines linked by a synthesis pathway. Each step requires an enzyme, and L-DOPA cannot be omitted.'),P('路径题的关键是找到“上一站”和“控制这一步的酶”。它能同时解决直接前体、限速因素和阻断后的上下游预测。','Pathway questions ask for the previous intermediate and the enzyme controlling the step. This solves immediate-precursor, rate-limit and blockade predictions together.'),[
 term('前体','Precursor','可用于制造后续物质的上游原料；直接前体必须紧邻目标前一步。','An upstream material used to make a product; an immediate precursor is the material just one step before it.'),term('TH 与 AADC','TH and AADC','TH 为 tyrosine hydroxylase；AADC 为 aromatic amino acid decarboxylase，也称 DOPA decarboxylase。','TH is tyrosine hydroxylase; AADC is aromatic amino acid decarboxylase, also called DOPA decarboxylase.'),term('DBH 与 PNMT','DBH and PNMT','DBH 为 dopamine β-hydroxylase；PNMT 为 phenylethanolamine N-methyltransferase，分别负责后两步。','Dopamine β-hydroxylase and phenylethanolamine N-methyltransferase catalyze the later two steps.')
],[
 step('起点变成 L-DOPA','Convert the starting material to L-DOPA','Tyrosine 经 TH 成为 L-DOPA。TH 催化经典限速步骤；它像流程中限制生产速度的一步，但真实限制来自酶活性和调节，不是字面上的工厂机器。','TH converts tyrosine to L-DOPA in the classical rate-limiting step. A production bottleneck is a useful analogy, but actual limitation comes from enzyme activity and regulation.'),
 step('直接制造 dopamine','Produce dopamine directly','AADC 将 L-DOPA 脱羧形成 dopamine。因此 tyrosine 是上游前体，L-DOPA 才是直接前体；原卷缺少 L-DOPA 选项要明确标注。','AADC decarboxylates L-DOPA to dopamine. Tyrosine is upstream, while L-DOPA is immediate. The original exam’s missing L-DOPA option must be flagged.'),
 step('有相应酶才继续','Continue only with the relevant enzymes','DBH 把 dopamine 变成 norepinephrine；PNMT 再把后者变成 epinephrine。并非每颗 dopamine 神经元都具备后两种酶。','DBH converts dopamine to norepinephrine, then PNMT converts norepinephrine to epinephrine. Not every dopamine neuron has both later enzymes.'),
 step('把合成与清除分开','Separate synthesis from clearance','释放后可由相应 Na⁺依赖转运体再摄取；MAO 参与单胺代谢，儿茶酚胺还可涉及 COMT。清除酶不等于合成酶。','After release, appropriate Na⁺-dependent transporters mediate uptake. MAO participates in monoamine metabolism, and catecholamines can also involve COMT. Clearance enzymes are not synthetic enzymes.')
],[P('教学干预：在合成通路其余条件相同的简化模型中，阻断 DBH 会减少 NE 生成，并减少它作为后续 E 前体的供给；上游 dopamine 可能积累。阻断 TH 则从较早步骤削弱下游儿茶酚胺合成。','Teaching intervention: with other synthesis-pathway conditions fixed, DBH blockade reduces NE production and its supply for epinephrine synthesis; upstream dopamine may accumulate. TH blockade reduces downstream catecholamine supply from an earlier step.'),P('这种预测要说清“简化模型”和“其他条件相同”。真实储备、清除和反馈会影响变化幅度与时间，不能由路径箭头推出即时精确浓度。','State the simplified-model and fixed-condition assumptions. Stores, clearance and feedback affect magnitude and timing, so pathway arrows do not determine exact immediate concentrations.')],P('Tyrosine 与 L-DOPA 都能参与 dopamine 合成，为何只有一个叫直接前体？','Why is only one of tyrosine and L-DOPA the immediate dopamine precursor?'),P('“直接”要求中间没有另一种代谢物。Tyrosine 还要先经 TH 生成 L-DOPA，L-DOPA 才由 AADC 变成 dopamine。','Immediate means no intervening metabolite. Tyrosine must first become L-DOPA through TH; AADC then converts L-DOPA into dopamine.'),'catecholamine');

L('c6-t7',P('Serotonin（5-HT）由 tryptophan 经两步生成，释放后通过再摄取和代谢结束作用。合成、原料供给与清除是不同环节。','Serotonin, or 5-HT, is synthesized from tryptophan in two steps, then cleared through uptake and metabolism. Synthesis, precursor supply and clearance are distinct stages.'),P('5-HT 和 dopamine 都是单胺，却不使用同样的起始原料和羟化酶。把两条路径并排比较，可以避免 TH 与 TPH 混写。','5-HT and dopamine are both monoamines but have different starting materials and hydroxylases. Comparing their pathways prevents confusion between TH and TPH.'),[
 term('Tryptophan 与 5-HTP','Tryptophan and 5-HTP','前者是起始氨基酸，后者是 5-hydroxytryptophan，紧邻 serotonin 的前一步。','Tryptophan is the starting amino acid; 5-hydroxytryptophan is the immediate precursor of serotonin.'),term('TPH','Tryptophan hydroxylase','催化 tryptophan→5-HTP 的限速酶，不是儿茶酚胺路径的 TH。','The rate-limiting enzyme converting tryptophan to 5-HTP, distinct from catecholamine TH.'),term('SERT 与 MAO','SERT and MAO','SERT 介导 serotonin 再摄取；MAO 是参与单胺代谢的酶。','SERT mediates serotonin uptake; MAO is an enzyme participating in monoamine metabolism.')
],[
 step('先羟化','Hydroxylate first','TPH 把 tryptophan 变成 5-HTP。要把酶和底物同时写清：名称中的 tryptophan 与 tyrosine 不同。','TPH converts tryptophan to 5-HTP. Specify enzyme and substrate: tryptophan differs from tyrosine.'),
 step('再脱羧','Then decarboxylate','AADC 把 5-HTP 变成 serotonin。AADC 也参与 L-DOPA→dopamine，但共享一个酶不表示两条路径的所有前体都相同。','AADC converts 5-HTP to serotonin. It also catalyzes L-DOPA→dopamine, but a shared enzyme does not make all pathway precursors identical.'),
 step('区分限速反应与原料供给','Distinguish reaction control from precursor supply','TPH 是限速反应的酶；tryptophan 可用量也影响合成。课堂强调原料量与教材强调酶并不必然冲突，它们回答不同层次的问题。','TPH catalyzes the rate-limiting reaction, while tryptophan availability also influences synthesis. Classroom emphasis on substrate and textbook emphasis on enzyme address complementary levels.'),
 step('清除影响暴露时长','Clearance affects exposure duration','SERT 通过 Na⁺依赖运输回收 5-HT，MAO 参与代谢。阻断回收可以延长外侧暴露，而不是直接提高合成反应速度。','SERT recovers 5-HT through Na⁺-dependent transport; MAO participates in metabolism. Uptake blockade can prolong extracellular exposure without directly accelerating synthesis.')
],[P('教学对比：药物 A 抑制 TPH，新 5-HT 的合成供给通常减少；药物 B 阻断 SERT，在释放仍进行且其他条件相同时，外侧 5-HT 可停留更久。两者都“影响 serotonin”，但方向与步骤不同。','Teaching comparison: inhibiting TPH usually reduces new 5-HT supply. Blocking SERT can prolong extracellular 5-HT exposure when release continues and other conditions are fixed. Both affect serotonin but at different steps and in different ways.'),P('不能仅凭外侧 5-HT 增多就断言某颗细胞一定更兴奋；还要知道受体亚型与回路。','More extracellular 5-HT does not alone prove that a particular cell becomes more excitable; receptor subtype and circuit still matter.')],P('“限速因素是 tryptophan”与“限速酶是 TPH”是否必须二选一？','Must precursor availability and TPH as the rate-limiting enzyme be mutually exclusive?'),P('不必。可把原料供给与催化反应分别说明，既回答课堂强调，也保持完整机制。不要用“Amount of 5-HT”替代尚未生成产物的原料限制。','No. Explain precursor supply and the catalytic reaction separately, addressing classroom emphasis while preserving the mechanism. Product amount should not replace the precursor-supply explanation.'));

L('c6-t8',P('Glutamate、GABA 和 glycine 是重要的氨基酸类递质。成熟神经系统中，前者常兴奋，后两者常参与抑制，但具体效应仍由受体和离子条件决定。','Glutamate, GABA and glycine are important amino-acid transmitters. In mature systems glutamate commonly excites, while GABA and glycine commonly inhibit, with receptor and ionic conditions determining the actual response.'),P('合成与降解酶常被交换成干扰项。尤其 GABA 是从 glutamate 生成的：同一分子在不同步骤和受体下可以对应不同功能。','Distractors often interchange synthesis and degradation enzymes. GABA is made from glutamate: different pathway positions and receptors matter more than a name alone.'),[
 term('GAD','Glutamic acid decarboxylase','把 glutamate 转为 GABA 的合成酶。','The synthetic enzyme converting glutamate into GABA.'),term('GABA transaminase','GABA transaminase','参与 GABA 代谢降解的酶。','An enzyme participating in GABA breakdown.'),term('解除抑制','Disinhibition','原先压低活动的输入减弱，使目标或回路更容易活跃。','Weakening an inhibitory input so that its target or circuit can become more active.')
],[
 step('从 glutamate 制造 GABA','Make GABA from glutamate','GAD 催化脱羧，使 glutamate 成为 GABA。抑制 GAD 主要影响新 GABA 供给，不能写成增强 GABA 合成。','GAD catalyzes decarboxylation of glutamate to GABA. GAD inhibition reduces new supply rather than increasing synthesis.'),
 step('降解是另一侧','Breakdown acts on a different side','GABA transaminase 参与降解；抑制它通常减少代谢清除。两类酶同属 GABA 系统，却不应预测成同样的分子变化。','GABA transaminase participates in breakdown; inhibiting it usually reduces metabolic removal. Both enzymes concern GABA but need not produce the same molecular change.'),
 step('受体把递质变成膜效应','Receptors convert transmitter into membrane effects','GABA_A 和 glycine 受体常增加 Cl⁻电导；GABA_B 可经 G 蛋白调节 K⁺或 Ca²⁺通道。glutamate 的 AMPA／NMDA／kainate 则是另一受体家族。','GABA_A and glycine receptors commonly increase Cl⁻ conductance; GABA_B can regulate K⁺ or Ca²⁺ channels through G proteins. AMPA/NMDA/kainate belong to the separate glutamate family.'),
 step('再从细胞推回路','Infer circuit consequences separately','成熟回路中失去 GABAergic 神经元常减少抑制、提高兴奋性。这个结论要保留受体、离子梯度与回路条件，不是所有细胞在任何阶段都同样。','Loss of GABAergic neurons commonly reduces inhibition and increases excitability in mature circuits. Retain receptor, gradient and circuit assumptions rather than generalizing to every cell and developmental condition.')
],[P('教学对比：A 组抑制 GAD，预期新 GABA 生成减少；B 组抑制 GABA transaminase，预期 GABA 降解减少。答题先定位箭头，再讨论可能的抑制变化。','Teaching comparison: GAD inhibition reduces new GABA production, whereas GABA-transaminase inhibition reduces GABA breakdown. Locate the affected arrow before discussing inhibition.'),P('若实验是直接减少 GABA 神经元数量，则常见成熟回路会失去部分“刹车”。刹车仅是解除抑制的类比，真实作用仍需通过受体与电导说明。','If the manipulation removes GABAergic neurons, a typical mature circuit loses part of its inhibitory “brake.” The analogy suggests disinhibition; the actual explanation still requires receptors and conductance.')],P('为什么“抑制一个抑制性神经元”可能让回路活动增加？','Why can inhibiting an inhibitory neuron increase circuit activity?'),P('因为减少的是原先对其他细胞的抑制输入。要按“干预对象→递质释放→目标细胞反应”追踪，不能只看到“抑制”两个字就判所有活动都下降。','The intervention reduces inhibition of other cells. Trace target → transmitter release → receiving response rather than assuming every use of “inhibit” lowers all circuit activity.'));

L('c6-t9',P('合成、囊泡装填、细胞膜再摄取、降解和受体结合，是递质通路中不同的位置。先定位干预，才能预测结果。','Synthesis, vesicular loading, membrane uptake, degradation and receptor binding occupy different pathway locations. Locate an intervention before predicting its result.'),P('“递质更多”可能指细胞质、囊泡或细胞外不同位置；“反应更大”也不等于药物直接激动受体。把位置说清，推理才有唯一含义。','More transmitter can mean more in cytoplasm, vesicles or extracellular fluid. A larger response does not prove direct receptor agonism. Specify location to make the prediction meaningful.'),[
 term('细胞膜转运体','Plasma-membrane transporter','连接细胞外与细胞内，许多再摄取过程利用 Na⁺梯度。','Connects extracellular and intracellular compartments; many uptake processes use a Na⁺ gradient.'),term('囊泡转运体','Vesicular transporter','把递质装进囊泡，通常依赖囊泡质子电化学梯度。','Loads transmitter into vesicles, usually using a proton electrochemical gradient.'),term('酶与受体','Enzyme and receptor','酶催化化学反应；受体识别配体并启动或调节信号。','Enzymes catalyze chemical reactions; receptors recognize ligands and initiate or regulate signaling.')
],[
 step('合成抑制减少新供给','Synthesis inhibition reduces new supply','已有储备可能使释放不会立刻完全消失。要区分直接分子变化与等待储备耗用后的现象。','Existing stores may delay loss of release. Distinguish the immediate molecular change from later consequences after stores are used.'),
 step('装填抑制改变囊泡内容','Loading inhibition changes vesicular content','细胞质可能仍有递质，但囊泡无法正常获得它。检测总细胞含量正常，不足以保证每个囊泡有足够可释放内容。','Cytoplasmic transmitter may remain while vesicles fail to load normally. Normal total cellular content does not guarantee adequate releasable vesicular content.'),
 step('再摄取与降解控制清除','Uptake and degradation control clearance','阻断回收常延长细胞外暴露；抑制降解也可能减少清除。二者过程不同，都不应直接写成“增加了合成酶活性”。','Uptake blockade commonly prolongs extracellular exposure; degradation inhibition can also reduce removal. Neither should be directly described as increased synthetic-enzyme activity.'),
 step('受体干预改变接收','Receptor intervention changes reception','在相同递质浓度下，拮抗相应受体可减弱响应。若要断言直接 agonist，则需要直接激活受体的证据，而不只测外侧浓度。','At the same transmitter concentration, antagonizing its receptor can reduce response. Direct agonism requires receptor-activation evidence, not merely an extracellular concentration measurement.')
],[P('教学情境：药物不结合受体，却让递质停留时间延长。优先考虑清除环节，而不是仅凭反应变大就叫 agonist。另一处理使囊泡内容减少但细胞质含量仍在，则优先考虑装填。','Teaching scenario: a drug prolongs transmitter residence without binding the receptor, suggesting clearance rather than direct agonism. Reduced vesicular content with retained cytoplasmic transmitter instead suggests loading impairment.'),P('这些是其他条件固定的课堂预测。反馈、储备与受体变化可能改变真实时间进程，不能只凭单一结果锁定唯一靶点。','These are classroom predictions with other conditions fixed. Feedback, stores and receptor changes can alter timing, so one outcome does not uniquely establish a target.')],P('总细胞递质含量正常，为什么突触传递仍可能变弱？','Why can transmission weaken despite normal total cellular transmitter?'),P('递质可能没有被正确装入囊泡，释放机器可能受阻，或后侧受体可能无效。总量没有同时回答位置、可释放性和接收能力。','Loading, release machinery or postsynaptic receptors may be impaired. Total amount does not establish location, releasability or receiving capacity.'));

L('c6-t10',P('三个章节讲的是一条连续消息链：准备递质→传来 AP→释放→受体响应→PSP 整合→下一次 AP。','The chapters form one message chain: prepare transmitter → arriving AP → release → receptor response → PSP integration → the next AP.'),P('同样“没有后侧反应”，可能因为链上不同步骤失败。跨章题的目标是定位失败范围，并设计能绕过某一步的比较。','A missing postsynaptic response can result from failure at different steps. Cross-chapter reasoning locates a range of defects and designs comparisons that bypass a step.'),[
 term('上游与下游','Upstream and downstream','沿机制顺序，较早步骤称上游，较晚步骤称下游。','Earlier versus later positions along a causal pathway.'),term('旁路／救援','Bypass/rescue','直接提供后续步骤需要的输入，查看是否恢复响应。','Supplying a later step’s input directly to test whether a response can be restored.'),term('定位范围','Localization range','某实验排除了或支持哪些环节；不一定能确定唯一分子。','The steps supported or excluded by a test, not necessarily one unique molecule.')
],[
 step('准备可释放资源','Prepare releasable resources','合成与囊泡装填使末梢有递质可用。资源存在还不表示已经收到释放触发。','Synthesis and loading supply releasable transmitter. Having resources does not mean the release trigger has arrived.'),
 step('电信号触发化学释放','Electrical arrival triggers chemical release','前突触 AP 打开 Ca²⁺通道，局部 Ca²⁺经传感器触发准备好的融合机器。这里区分 AP 到达、Ca²⁺进入和胞吐三个步骤。','The presynaptic AP opens Ca²⁺ channels; local Ca²⁺ and sensors trigger prepared fusion machinery. Separate AP arrival, Ca²⁺ entry and exocytosis.'),
 step('接收与整合','Receive and integrate','递质激活受体，改变后侧电导或细胞内信号。EPSP／IPSP 的传播、重叠和分流共同影响初始段阈值。','Transmitter activates receptors, changing postsynaptic conductance or intracellular signaling. PSP spread, overlap and shunting influence threshold at the initial segment.'),
 step('按步骤做旁路测试','Use a stepwise bypass test','若前突触刺激失败却直接给递质仍有效，支持受体与其后通路可用，故障偏向被绕过的上游。再测 AP、Ca²⁺或释放量才能细分。','If presynaptic stimulation fails but direct transmitter still works, receptors/downstream signaling remain responsive and a bypassed upstream defect is supported. AP, Ca²⁺ or release measurements refine localization.')
],[P('教学定位：处理后没有 EPSP。直接施加正常递质恢复了响应，说明不能立刻把问题写成“受体坏了”。下一步若发现 AP 正常、Ca²⁺进入减少，就更支持释放触发之前或该处的障碍。','Teaching localization: treatment abolishes an EPSP, but direct normal transmitter restores it. Do not immediately blame the receptor. If APs remain normal while Ca²⁺ entry decreases, evidence points toward the release-triggering region of the pathway.'),P('反过来，直接递质也无效时，还须检查给药剂量、受体、下游和细胞活性，不能只用一次阴性结果宣布某个特定受体蛋白消失。','If direct transmitter also fails, examine delivery, dose, receptors, downstream signaling and viability. One negative result cannot prove disappearance of one specific receptor protein.')],P('为什么“救回响应”能缩小范围，却不一定锁定唯一分子？','Why can rescue narrow a defect without identifying one molecule?'),P('旁路一次越过了多个上游步骤；其中任何一步故障都可能被绕过。需要额外测量把这个范围进一步分开。','A bypass skips several upstream steps at once, and failure at any of them may be bypassed. Additional measurements are needed to separate that range.'));

const escape=value=>String(value??'').replace(/[&<>"']/g,ch=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]));
const bilingual=p=>`<span lang="zh-CN">${escape(p.zh)}</span><span lang="en" class="translation">${escape(p.en)}</span>`;
const heading=(zh,en)=>`<h4>${bilingual(P(zh,en))}</h4>`;
function renderLesson(id,{print=false,figureHTML=''}={}){
 const l=lessons[id];if(!l)return '';
 return `<div class="beginner-lesson" data-lesson="${escape(id)}"><p class="lesson-kicker">从零学 / START FROM THE BEGINNING</p>
 <section class="lesson-section">${heading('这是什么，为什么需要它','What it is and why it matters')}<p class="lead">${bilingual(l.summary)}</p><p>${bilingual(l.why)}</p></section>
 <section class="lesson-section">${heading('先认识几个词','Meet the essential terms')}<dl class="lesson-terms">${l.terms.map(([name,meaning])=>`<div><dt>${bilingual(name)}</dt><dd>${bilingual(meaning)}</dd></div>`).join('')}</dl></section>
 <section class="lesson-section">${heading('一步一步发生什么','Follow the mechanism step by step')}<ol class="lesson-steps">${l.steps.map(([title,body])=>`<li><h5>${bilingual(title)}</h5><p>${bilingual(body)}</p></li>`).join('')}</ol>${figureHTML}</section>
 <section class="lesson-section lesson-example">${heading('跟着例子理解','Work through an example')}<p class="small">教学示例，用于解释机制，并非原卷实测数据。<span lang="en" class="translation">A teaching example, not measured data from the original exam.</span></p>${l.example.map(p=>`<p>${bilingual(p)}</p>`).join('')}</section>
 <section class="lesson-section lesson-understanding">${heading('检查是否理解','Check your understanding')}<p>${bilingual(l.check.prompt)}</p><details class="lesson-check-answer"${print?' open':''}><summary>展开参考解释<span class="translation" lang="en">Show the explanation</span></summary><p>${bilingual(l.check.answer)}</p></details><p class="small">口头理解题，不计分，不改变练习或模拟卷记录。<span class="translation" lang="en">An ungraded reflection; it does not change practice or exam records.</span></p></section></div>`;
}
function renderFoundations({print=false}={}){
 return `<div class="foundation-heading"><p class="eyebrow">BEFORE CHAPTER 4</p><h3>${bilingual(P('第一次学，先读这六件事','Six starting points for first-time learners'))}</h3><p>${bilingual(P('不需要先背公式。先分清位置、离子和信号，再进入下面的知识点。','Start with locations, ions and signals before memorizing equations or moving into the lessons.'))}</p></div>`+foundations.map((f,i)=>`<details class="foundation-unit" id="${f.id}"${print||i===0?' open':''}><summary>${bilingual(f.title)}</summary>${f.body.map(p=>`<p>${bilingual(p)}</p>`).join('')}<div class="source-refs">${f.sources.map(([key,locator])=>`<a href="/studyguides/neuroscience/sources/Neuroscience_%20Exploring%20the%20Brain%20(2015).pdf#page=${Number(locator.match(/p\.(\d+)/)?.[1])||100}" target="_blank" rel="noopener">${escape(key+' · '+locator)} ↗</a>`).join('')}</div></details>`).join('');
}
function renderMapSummary(id){const l=lessons[id];return l?`<div class="map-beginner-summary"><p>${bilingual(l.summary)}</p><p>${bilingual(l.why)}</p></div>`:'';}
return {foundations,lessons,renderLesson,renderFoundations,renderMapSummary};
});
